    function sppStampCardHideFlags() {
        const root = document.documentElement.classList;
        CARD_HIDE_SHAPES.forEach(function (sh) {
            const on = {};
            CARD_HIDE_ITEMS.forEach(function (it) {
                const raw = GM_getValue(sh.key + it[0], null);
                const v = (raw === null || raw === undefined || raw === '') ? false
                    : (typeof raw === 'string' ? raw.toLowerCase() !== 'false' : !!raw);
                on[it[0]] = v;
                if (v) root.add(sh.cls + it[1]);
            });
            

            if (on._av && on._nm) root.add(sh.cls + '-noavnm');
            if (on._av && on._nm && on._dt) root.add(sh.cls + '-nometa');
        });
    }

    










