    function getImgSrc(img) {
        return img.getAttribute('data-src')
            || img.getAttribute('data-original')
            || img.getAttribute('data-lazy-src')
            || img.getAttribute('file')
            || img.src || '';
    }

    function isContentImage(img) {
        const src = getImgSrc(img);
        if (!src || src === 'about:blank' || src.startsWith('data:')) return false;
        if (src.includes('/images/post/smile/')) return false;
        if (src.includes('/images/colorImagination/')) return false;
        if (src.includes('noimageavailble')) return false;
        if (img.naturalWidth > 0 && img.naturalWidth < 80 && img.naturalHeight > 0 && img.naturalHeight < 80) return false;
        return true;
    }

    
    
    
    let domReadySeq = 0;
    function onDomReady(fn) {
        const seq = ++domReadySeq;
        const run = function () {
            try {
                fn();
            } catch (e) {
                SPP_INIT.fail.push('DOMReady#' + seq + ' ⇒ ' + errBrief(e));
                console.error('[SPP] DOMReady 回调#' + seq + ' 初始化失败', e);
            }
        };
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', run);
        } else {
            run();
        }
    }

    
    function appendToHeadSafe(el) {
        const parent = document.head || document.documentElement || document.body;
        if (parent) {
            parent.appendChild(el);
        } else {
            document.addEventListener('DOMContentLoaded', () => {
                (document.head || document.documentElement || document.body).appendChild(el);
            }, { once: true });
        }
    }

    
    function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

    
    function waitForElement(selector, maxRetries, interval) {
        maxRetries = maxRetries || 30;
        interval = interval || 500;
        return new Promise(function (resolve) {
            var tries = 0;
            (function check() {
                var el = document.querySelector(selector);
                if (el) { resolve(el); return; }
                if (++tries >= maxRetries) { resolve(null); return; }
                setTimeout(check, interval);
            })();
        });
    }

    
    
    
    
    
    
    
    
    
