    let heatStyleMemo = null;
    const SPP_CONFIG = {
        
        bool(key, dflt) {
            const raw = GM_getValue(key, null);
            if (raw === null || raw === undefined || raw === '') return dflt;
            return typeof raw === 'string' ? raw.toLowerCase() !== 'false' : !!raw;
        },
        
        
        
        
        
        
        num(key, dflt, min, max) {
            const stored = cfgFit(GM_getValue(key, null), min, max, min > 0);
            if (stored !== null) return stored;
            const d = Number(dflt);
            if (isFinite(d) && d >= min && d <= max) return d;
            return min;
        },
        
        pick(key, dflt, allowed) {
            const stored = String(GM_getValue(key, null) || '');
            if (stored && allowed.indexOf(stored) >= 0) return stored;
            return allowed.indexOf(dflt) >= 0 ? dflt : allowed[0];
        },
        
        
        text(key, dflt) {
            const raw = GM_getValue(key, null);
            if (raw === null || raw === undefined) return dflt;
            return typeof raw === 'string' ? raw : String(raw);
        },
        
        imgNumber(field, min, max) {
            const stored = cfgFit(cfgJsonNum(GM_getValue(IMG_SETTINGS_KEY, null), field), min, max, true);
            if (stored !== null) return stored;
            const d = Number(IMG_DEFAULTS[field]);
            return isFinite(d) ? d : min;
        },
        imgBool(field) {
            let raw = null;
            try {
                const s = GM_getValue(IMG_SETTINGS_KEY, null);
                if (s) {
                    const o = JSON.parse(s);
                    if (o && typeof o === 'object' && o[field] !== undefined && o[field] !== null) raw = o[field];
                }
            } catch (_) { raw = null; }
            if (raw !== null) return typeof raw === 'string' ? raw.toLowerCase() !== 'false' : !!raw;
            return !!IMG_DEFAULTS[field];
        },
        imgString(field, allowed) {
            let raw = null;
            try {
                const s = GM_getValue(IMG_SETTINGS_KEY, null);
                if (s) { const o = JSON.parse(s); if (o && typeof o === 'object') raw = o[field]; }
            } catch (_) { raw = null; }
            const v = raw === null || raw === undefined ? '' : String(raw);
            if (v && allowed.indexOf(v) >= 0) return v;
            const d = String(IMG_DEFAULTS[field]);
            return allowed.indexOf(d) >= 0 ? d : allowed[0];
        },
        
        imgSettings() {
            return {
                maxImgHeight: this.imgNumber('maxImgHeight', 30, 100),
                maxImgWidth:  this.imgNumber('maxImgWidth', 20, 100),
                thumbSize:    this.imgNumber('thumbSize', 32, 128),
                centerImg:    this.imgBool('centerImg'),
                wheelAction:  this.imgString('wheelAction', ['switch', 'zoom'])
            };
        },
        









        heatStyle() {
            if (heatStyleMemo) return heatStyleMemo;
            let raw = null;
            try {
                const stored = GM_getValue(HEAT_STYLE_KEY, null);
                if (stored) {
                    const o = JSON.parse(stored);
                    if (o && typeof o === 'object') raw = o;
                }
            } catch (_) { raw = null; }
            const pickColor = (k) => {
                const v = (raw && typeof raw[k] === 'string') ? raw[k].trim() : '';
                return HEAT_COLOR_RE.test(v) ? v : HEAT_STYLE_DEFAULTS[k];
            };
            const bounds = ['tCold', 'tWarm', 'tHot'].map((k) => {
                const v = cfgFit(raw ? raw[k] : null, 0, HEAT_STYLE_MAX, false);
                return v === null ? HEAT_STYLE_DEFAULTS[k] : v;
            }).sort((a, b) => a - b);
            heatStyleMemo = {
                tCold: bounds[0], tWarm: bounds[1], tHot: bounds[2],
                cCold: pickColor('cCold'), cWarm: pickColor('cWarm'),
                cHot: pickColor('cHot'), cPeak: pickColor('cPeak')
            };
            return heatStyleMemo;
        },
        




        heatScope() {
            const stored = String(GM_getValue(HEAT_SCOPE_KEY, null) || '');
            if (HEAT_SCOPE_ALLOWED.indexOf(stored) >= 0) return stored;
            return SPP_CONFIG.bool(HEAT_SCOPE_LEGACY_KEY, false) ? 'flame_title' : HEAT_SCOPE_DEFAULT;
        }
        
        
        
        
    };

    
    
    
    
    
    const SEARCH_ORDER_ALLOWED = ['hits', 'replies', 'postdate', 'lastpost'];
    const SEARCH_ORDER_LABEL = { hits: '人气', replies: '回复', postdate: '发帖时间', lastpost: '最后回复' };
    function searchOrder() {
        return SPP_CONFIG.pick('spp_search_order', 'hits', SEARCH_ORDER_ALLOWED);
    }

    
    
    
    
    
    
