        const SPP_PANE_STORE = 'spp_pane';

        

        function stampPanelPanes(overlay) {
            let n = 0;
            overlay.querySelectorAll('.spp-gs-row').forEach(function (row) {
                const p = row.dataset.key ? SPP_PANE_OF[row.dataset.key] : '';
                if (p) { row.dataset.pane = p; n++; }
                else SPP_INIT.fail.push('设置面板页签归类漏登记：' + (row.dataset.key || '(没有 data-key 的行)'));
            });
            

            const ACTS = [['.spp-gs-actbtn', 'look'], ['.spp-eh-n', 'emoji'], ['.spp-read-count', 'misc']];
            overlay.querySelectorAll('.spp-gs-act').forEach(function (act) {
                const hit = ACTS.filter(function (t) { return act.querySelector(t[0]); })[0];
                if (hit) { act.dataset.pane = hit[1]; n++; }
                else SPP_INIT.fail.push('设置面板页签归类漏登记：动作行');
            });
            
            Object.keys(SPP_PANE_OF).forEach(function (k) {
                if (!overlay.querySelector('.spp-gs-row[data-key="' + k + '"]')) {
                    SPP_INIT.fail.push('设置面板页签归类写了个面板上没有的键：' + k);
                }
            });
            return n;
        }

        


        function applyPanelPane(overlay) {
            const box = overlay.querySelector('#spp-global-settings-box');
            if (!box) return;
            const qEl = box.querySelector('.spp-pane-q');
            const q = (qEl && qEl.value ? qEl.value : '').trim().toLowerCase();
            const filtering = q.length > 0;
            const active = box.dataset.paneCur || SPP_PANES[0].id;
            const hit = {};
            SPP_PANES.forEach(function (p) { hit[p.id] = 0; });
            box.querySelectorAll('[data-pane]').forEach(function (el) {
                const show = filtering
                    ? (el.textContent || '').toLowerCase().indexOf(q) >= 0
                    : el.dataset.pane === active;
                el.classList.toggle('spp-pane-hidden', !show);
                if (show) hit[el.dataset.pane] = (hit[el.dataset.pane] || 0) + 1;
            });
            let any = false;
            SPP_PANES.forEach(function (p) { if (hit[p.id] > 0) any = true; });
            box.querySelectorAll('.spp-pane').forEach(function (b) {
                const on = !filtering && b.dataset.goto === active;
                b.classList.toggle('spp-pane--on', on);
                b.setAttribute('aria-selected', on ? 'true' : 'false');
                b.classList.toggle('spp-pane--dim', filtering && !hit[b.dataset.goto]);
            });
            const empty = box.querySelector('.spp-pane-empty');
            if (empty) empty.classList.toggle('spp-pane-on', filtering && !any);
        }

        
        function wirePanelPanes(overlay) {
            const box = overlay.querySelector('#spp-global-settings-box');
            if (!box) return;
            stampPanelPanes(overlay);
            try {
                const last = sessionStorage.getItem(SPP_PANE_STORE);
                if (last && SPP_PANES.some(function (p) { return p.id === last; })) box.dataset.paneCur = last;
            } catch (e) {}
            if (!box.dataset.paneCur) box.dataset.paneCur = SPP_PANES[0].id;
            const go = function (id) {
                box.dataset.paneCur = id;
                try { sessionStorage.setItem(SPP_PANE_STORE, id); } catch (e) {}
                applyPanelPane(overlay);
            };
            const clearQ = function () {
                const qEl = box.querySelector('.spp-pane-q');
                if (qEl && qEl.value) qEl.value = '';
            };
            const bar = box.querySelector('.spp-panebar');
            if (bar) {
                bar.addEventListener('click', function (ev) {
                    const btn = ev.target && ev.target.closest ? ev.target.closest('.spp-pane') : null;
                    if (!btn || !btn.dataset.goto) return;
                    
                    clearQ();
                    go(btn.dataset.goto);
                });
                bar.addEventListener('keydown', function (ev) {
                    if (ev.key !== 'ArrowLeft' && ev.key !== 'ArrowRight') return;
                    const ids = SPP_PANES.map(function (p) { return p.id; });
                    const d = ev.key === 'ArrowRight' ? 1 : -1;
                    const nx = ids[(ids.indexOf(box.dataset.paneCur) + d + ids.length) % ids.length];
                    clearQ();
                    go(nx);
                    const f = box.querySelector('.spp-pane[data-goto="' + nx + '"]');
                    if (f) f.focus();
                    ev.preventDefault();
                });
            }
            const q = box.querySelector('.spp-pane-q');
            if (q) q.addEventListener('input', function () { applyPanelPane(overlay); });
            applyPanelPane(overlay);
        }

