                if (wipeBtn.dataset.sppArmed !== '1') {
                    wipeBtn.dataset.sppArmed = '1';
                    wipeBtn.textContent = '确定清空？';
                    if (wipeTimer) clearTimeout(wipeTimer);
                    wipeTimer = setTimeout(function () {
                        wipeBtn.dataset.sppArmed = '';
                        wipeBtn.textContent = '清除全部记录';
                    }, 4000);
                    return;
                }
                let res = { removed: 0, left: 0 };
                try { res = readWipeNow(); } catch (e) { res = { removed: 0, left: 0 }; }
                wipeBtn.dataset.sppArmed = '';
                if (wipeTimer) { clearTimeout(wipeTimer); wipeTimer = 0; }
                const cnt = overlay.querySelector('.spp-read-count');
                if (cnt) cnt.textContent = String(res.left);
                wipeBtn.textContent = res.removed > 0 ? ('已清空 ' + res.removed + ' 条') : '本来就没有记录';
                setTimeout(function () { wipeBtn.textContent = '清除全部记录'; }, 2400);
