        function norm(str) { return str.replace(/ /g, ' ').trim(); }

        function reformatAuthorDate(li) {
            const intro = li.querySelector('.section-intro');
            if (!intro || intro.dataset.sppTlDone) return;
            intro.dataset.sppTlDone = '1';
            intro.style.backgroundColor = 'transparent';
            const tds = intro.querySelectorAll('td');
            let author = '', date = '';
            tds.forEach(td => {
                const text = norm(td.textContent);
                if (/作者/.test(text)) {
                    const a = td.querySelector('a');
                    author = a ? a.textContent.trim() : text.replace(/.*作者[：:]\s*/, '');
                } else if (/\d{4}-\d{2}-\d{2}/.test(text)) {
                    const m = text.match(/(\d{4}-\d{2}-\d{2})/);
                    date = m ? m[1] : '';
                }
            });
            if (author || date) {
                const newContent = document.createElement('span');
                newContent.className = 'spp-tl-author-line';
                newContent.textContent = author + (date ? ' - 发布于 ' + date : '');
                newContent.style.cssText = 'color:#999;font-size:12px;';
                
                
                
                const aLink = intro.querySelector('td a');
                if (aLink && aLink.getAttribute('href')) {
                    newContent.dataset.sppAuthorHref = aLink.getAttribute('href');
                }
                intro.innerHTML = '';
                intro.appendChild(newContent);
            }
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
