        function evaluateCardImages(li) {
            const imgs = Array.from(li.querySelectorAll('img'));
            let hasValidImage = false;
            let hasPendingImage = false;

            imgs.forEach(img => {
                if (!img.dataset.sppImageWatch) {
                    img.dataset.sppImageWatch = '1';
                    img.addEventListener('load', function () {
                        delete img.dataset.sppImageLoadFailed;
                        evaluateCardImages(li);
                        
                        
                        
                        coverSweep();
                        
                        
                        
                        markCardOrientation(li);
                    });
                    img.addEventListener('error', function () {
                        img.dataset.sppImageLoadFailed = '1';
                        evaluateCardImages(li);
                    });
                }

                const state = getCardImageState(img);
                if (state === 'valid') hasValidImage = true;
                if (state === 'pending') hasPendingImage = true;
            });

            if (!hasValidImage && !hasPendingImage) {
                convertCardToList(li);
            }
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        function markCardOrientation(li) {
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            if (li.classList.contains('spp-tl-list')) {
                if (li.classList.contains('spp-card-portrait')) li.classList.remove('spp-card-portrait');
                return false;
            }
            const img = li.querySelector('.section-text img') || li.querySelector('img');
            if (!img || !img.naturalWidth || !img.naturalHeight) return false;

            const isPortrait = (img.naturalWidth / img.naturalHeight) < 1;
            const hasPortrait = li.classList.contains('spp-card-portrait');
            if (isPortrait && !hasPortrait) li.classList.add('spp-card-portrait');
            else if (!isPortrait && hasPortrait) li.classList.remove('spp-card-portrait');
            return isPortrait;
        }

        
        
        
        
        
        
        
        
        function buildCardMeta(li) {
            if (li.dataset.sppMetaDone) return;
            const sectionText = li.querySelector('.section-text');
            if (!sectionText) return;
            const spans = Array.from(sectionText.children).filter(c => c.tagName === 'SPAN');
            if (!spans.length) return;
            li.dataset.sppMetaDone = '1';
            const meta = document.createElement('div');
            meta.className = 'spp-card-meta';
            spans.forEach(s => meta.appendChild(s));
            sectionText.parentNode.insertBefore(meta, sectionText.nextSibling);
            
            if (li.classList.contains('spp-tl-list')) li.classList.add('spp-has-meta');
        }

        
        
        
        
        
        
        
        
        
        
        function relativeLuminance(rgb) {
            const m = String(rgb).match(/(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)[,\s]+(\d+(?:\.\d+)?)/);
            if (!m) return null;
            const [r, g, b] = [1, 2, 3].map(i => {
                let v = parseFloat(m[i]) / 255;
                return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
            });
            return 0.2126 * r + 0.7152 * g + 0.0722 * b;
        }

        const CARD_BG_LUM = relativeLuminance('rgb(19,26,42)');   
        const READABLE_MIN = '#9AA5BB';

        function ensureReadable(el, minRatio) {
            if (!el) return false;
            
            
            
            
            
            
            if (el.getAnimations) {
                el.getAnimations().forEach(anim => {
                    if (anim.transitionProperty === 'color') anim.cancel();
                });
            }
            
            
            
            const inlineColor = (el.style && el.style.color) ? String(el.style.color).trim() : '';
            if (inlineColor && relativeLuminance(inlineColor) === null) return false;
            const cs = getComputedStyle(el);
            const fg = (inlineColor && relativeLuminance(inlineColor) !== null)
                ? relativeLuminance(inlineColor)
                : relativeLuminance(cs.color);
            if (fg === null) return false;
            const ratio = (Math.max(fg, CARD_BG_LUM) + 0.05) / (Math.min(fg, CARD_BG_LUM) + 0.05);
            if (ratio >= (minRatio || 3)) return false;

            
            el.style.setProperty('color', READABLE_MIN, 'important');
            el.dataset.sppContrast = '1';
            return true;
        }

        
        
        
        const CONTRAST_MIN = { title: 3, reply: 3, heat: 3, name: 4.5, date: 3, fav: 3 };

        function fixDarkTextContrast(li) {
            let fixed = 0;
            const bump = (el, min) => { if (ensureReadable(el, min)) fixed++; };
            li.querySelectorAll('.section-title a').forEach(el => bump(el, CONTRAST_MIN.title));
            li.querySelectorAll('.spp-tl-reply').forEach(el => bump(el, CONTRAST_MIN.reply));
            li.querySelectorAll('.spp-tl-heat').forEach(el => bump(el, CONTRAST_MIN.heat));
            li.querySelectorAll('.spp-name-txt').forEach(el => bump(el, CONTRAST_MIN.name));
            li.querySelectorAll('.spp-date-txt').forEach(el => bump(el, CONTRAST_MIN.date));
            li.querySelectorAll('.spp-fav-txt').forEach(el => bump(el, CONTRAST_MIN.fav));
            
            
            
            
            
            
            
            li.querySelectorAll('.section-title a font[color], .section-title a [style*="color"]')
                .forEach(el => bump(el, CONTRAST_MIN.title));
            return fixed;
        }

