        function hashHue(str) {
            let h = 7;
            const s = String(str || '');
            for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
            return h % 360;
        }

        function buildCardByline(li) {
            if (li.dataset.sppBylineDone) return;
            const intro = li.querySelector('.section-intro');
            if (!intro) return;

            
            let author = '', authorHref = '', date = '';
            const flat = intro.querySelector('.spp-tl-author-line');
            if (flat) {
                const t = norm(flat.textContent);
                const m = t.match(/^(.*?)\s*-\s*发布于\s*(\d{4}-\d{2}-\d{2})/);
                if (m) { author = m[1].trim(); date = m[2]; }
                else { author = t; }
                
                
                authorHref = flat.dataset.sppAuthorHref || '';
            } else {
                Array.from(intro.querySelectorAll('td')).forEach(td => {
                    const text = norm(td.textContent);
                    if (/作者/.test(text)) {
                        const a = td.querySelector('a');
                        author = a ? a.textContent.trim() : text.replace(/.*作者[：:]\s*/, '');
                        if (a) authorHref = a.getAttribute('href') || '';
                    } else if (/\d{4}-\d{2}-\d{2}/.test(text)) {
                        const m = text.match(/(\d{4}-\d{2}-\d{2})/);
                        if (m) date = m[1];
                    }
                });
            }
            if (!author && !date) return;
            li.dataset.sppBylineDone = '1';

            const h1 = hashHue(author || date);
            const h2 = (h1 + 58) % 360;

            const byline = document.createElement('span');
            byline.className = 'spp-byline';
            byline.style.setProperty('--spp-h1', String(h1));
            byline.style.setProperty('--spp-h2', String(h2));

            if (author) {
                const name = document.createElement('span');
                name.className = 'spp-name';
                const avatar = document.createElement('span');
                avatar.className = 'spp-avatar';
                avatar.textContent = author[0] || '?';
                const txt = authorHref ? document.createElement('a') : document.createElement('span');
                txt.className = 'spp-name-txt';
                txt.textContent = author;
                if (authorHref) {
                    txt.setAttribute('href', authorHref);
                    txt.setAttribute('target', '_blank');
                }
                name.appendChild(avatar);
                name.appendChild(txt);
                byline.appendChild(name);
            }
            if (date) {
                const d = document.createElement('span');
                d.className = 'spp-date';
                const dt = document.createElement('span');
                dt.className = 'spp-date-txt';
                dt.textContent = date;
                d.appendChild(dt);
                byline.appendChild(d);
            }

            
            intro.innerHTML = '';
            intro.appendChild(byline);
        }

        
        
        
        
