    function initHeaderBits() {
        const SVG_NS = 'http://www.w3.org/2000/svg';
        const ICON = '<rect x="0.75" y="1" width="14.5" height="10" rx="1.7"/>' +
                     '<path d="M1.5 2.2 L8 6.7 L14.5 2.2"/>';

        
        function blankLinks() {
            const want = { '搜索': 1, '社区论坛任务': 1 };
            let matched = 0;
            [].slice.call(document.querySelectorAll('#mainNav a, ul.guide a')).forEach(a => {
                const t = (a.textContent || '').replace(/\s+/g, '');
                if (!want[t]) return;
                matched++;
                if (a.getAttribute('target') === '_blank' &&
                    a.getAttribute('rel') === 'noopener noreferrer') return;
                a.setAttribute('target', '_blank');
                a.setAttribute('rel', 'noopener noreferrer');
            });
            return matched;
        }

        
        function makeSvg() {
            const svg = document.createElementNS(SVG_NS, 'svg');
            svg.setAttribute('viewBox', '0 0 16 12');
            svg.setAttribute('width', '16');
            svg.setAttribute('height', '12');
            svg.setAttribute('fill', 'none');
            svg.setAttribute('stroke', '#fff');
            svg.setAttribute('stroke-width', '1.2');
            svg.setAttribute('stroke-linecap', 'round');
            svg.setAttribute('stroke-linejoin', 'round');
            svg.setAttribute('class', 'spp-mail-ic');
            svg.setAttribute('aria-hidden', 'true');
            svg.style.cssText = 'position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);pointer-events:none;';
            svg.innerHTML = ICON;
            return svg;
        }
        function mailIcon() {
            const a = document.getElementById('td_msg');
            if (!a) return false;
            const img = a.querySelector('img');
            if (img) img.style.setProperty('visibility', 'hidden', 'important');
            a.style.setProperty('position', 'relative', 'important');
            let svg = a.querySelector('svg.spp-mail-ic');
            if (!svg) { svg = makeSvg(); a.appendChild(svg); }
            
            if (!a.__sppMailWatch) {
                a.__sppMailWatch = new MutationObserver(() => { mailIcon(); });
                a.__sppMailWatch.observe(a, { childList: true, subtree: true, attributes: true, attributeFilter: ['src'] });
            }
            return true;
        }

        let tries = 0;
        (function boot() {
            const icon = mailIcon();
            const n = blankLinks();
            
            if ((icon && n >= 2) || tries++ >= 40) return;
            setTimeout(boot, 300);
        })();
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
