        const SPP_URL_RE = /https?:\/\/[^\s<>"'【】\u3000-\u303f\u4e00-\u9fff\u3040-\u30ff\uff00-\uffef]+/g;
        const SPP_OPEN_TAG_RE = /\[(?:img|media|url|email|flash|wmv|rm)(?:=[^\]]*)?\]?\s*$/i;

        






        const SPP_BARE_RE = /(^|[^0-9A-Za-z_@.\/-])((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,})((?::\d{2,5})?(?:\/[^\s<>"'【】\u3000-\u303f\u4e00-\u9fff\u3040-\u30ff\uff00-\uffef]*)?)/gi;

        

        const SPP_TLDS = ('com net org edu gov mil int info biz name pro aero coop museum io co me tv cc li moe '
            + 'cn tw hk jp kr sg my th vn ph id in pk au nz uk de fr nl be it es pt se no dk fi is ie ch at pl cz sk hu ro bg gr tr ru ua by kz il sa ae eg za br mx ar cl pe us ca gg la ly to ws pw ne nu tk ml ga cf st su ac sh im '
            + 'top site space xyz club online store shop app dev tech art design live life world today news blog pub win bid loan icu vip wang ren kim work link click press host cloud fun website company network wiki media agency digital studio software mobile tools email zone center city plus love one')
            .split(' ');

        




        const SPP_SELF_HOSTS = ['blue-plus.net', 'south-plus.net', 'south-plus.org', 'north-plus.net', 'east-plus.net', 'white-plus.net', 'level-plus.net', 'spring-plus.net', 'summer-plus.net', 'snow-plus.net', 'soul-plus.net', 'imoutolove.me'];
        const SPP_IMG_EXT_RE = /\.(?:jpe?g|png|gif|webp|bmp|avif)$/i;
        const SPP_FILE_EXT_RE = /\.(?:zip|rar|7z|mp4|webm|mkv|txt|pdf)$/i;
        function sppSelfKind(url) {
            let u;
            try { u = new URL(sppAbsUrl(url), location.href); } catch (e) { return ''; }
            const h = u.hostname.toLowerCase().replace(/^www\./, '');
            let self = false;
            for (let i = 0; i < SPP_SELF_HOSTS.length; i++) {
                const d = SPP_SELF_HOSTS[i];
                if (h === d || h.slice(-(d.length + 1)) === '.' + d) { self = true; break; }
            }
            if (!self) return '';
            const p = u.pathname.toLowerCase();
            if (SPP_IMG_EXT_RE.test(p)) return 'img';
            if (p.indexOf('/attachment/') >= 0 || p.indexOf('/thumb/') >= 0 || SPP_FILE_EXT_RE.test(p)) return 'self';
            return '';            
        }

        




        function sppImgLink(url) {
            let u;
            try { u = new URL(sppAbsUrl(url), location.href); } catch (e) { return false; }
            return SPP_IMG_EXT_RE.test(u.pathname);
        }

        

        const SPP_MULTI_SUFFIX = [
            'co.uk', 'org.uk', 'me.uk', 'ac.uk', 'gov.uk', 'com.cn', 'net.cn', 'org.cn', 'gov.cn', 'edu.cn',
            'com.tw', 'org.tw', 'com.hk', 'com.au', 'co.jp', 'co.kr', 'com.sg', 'com.my', 'com.br', 'com.mx',
            'pages.dev', 'github.io', 'gitlab.io', 'netlify.app', 'vercel.app', 'web.app', 'workers.dev',
            'firebaseapp.com', 'blogspot.com', 'herokuapp.com', 'onrender.com', 'glitch.me', 'repl.co',
            'cloudfront.net', 's3.amazonaws.com', 'r2.dev', 'nyc.mn'
        ];

        



        function siteNameOfHost(host) {
            const h = String(host || '').toLowerCase().replace(/\.$/, '');
            if (!h) return '';
            if (/^\d{1,3}(\.\d{1,3}){3}$/.test(h) || h.indexOf(':') >= 0) return h;
            const parts = h.split('.');
            if (parts.length < 2) return h;
            const last2 = parts.slice(-2).join('.');
            const keep = (SPP_MULTI_SUFFIX.indexOf(last2) >= 0 && parts.length >= 3)
                ? parts[parts.length - 3]
                : parts[parts.length - 2];
            const clean = String(keep || '').replace(/[^a-z0-9-]/g, '');
            if (!clean) return h;
            return clean.charAt(0).toUpperCase() + clean.slice(1);
        }

        

        


        function sppAbsUrl(url) {
            return /^[a-z][a-z0-9+.-]*:\/\//i.test(url) ? url : 'https://' + url;
        }

        function markNameOf(url) {
            const hit = imgHostOf(url);
            if (hit) return hit.name;
            let host = '';
            try { host = new URL(sppAbsUrl(url), location.href).hostname; } catch (e) { return ''; }
            return siteNameOfHost(host);
        }

        
        function imgHostOf(url) {
            let host = '';
            try { host = new URL(sppAbsUrl(url), location.href).hostname.toLowerCase(); } catch (e) { return null; }
            if (!host) return null;
            host = host.replace(/^www\./, '');
            

            for (let i = 0; i < IMG_HOSTS_LOOKUP.length; i++) {
                const h = IMG_HOSTS_LOOKUP[i];
                for (let j = 0; j < h.hosts.length; j++) {
                    const d = h.hosts[j];
                    if (host === d || host.slice(-(d.length + 1)) === '.' + d) return h;
                }
            }
            return null;
        }

        





        function annotateHostMark(ta, stats) {
            const src = ta.value || '';
            if (!src) return 0;
            const spans = [];                 
            const taken = [];                 
            let m;
            SPP_URL_RE.lastIndex = 0;
            while ((m = SPP_URL_RE.exec(src)) !== null) {
                spans.push({ pos: m.index, url: m[0] });
                taken.push([m.index, m.index + m[0].length]);
            }
            const inTaken = function (at) {
                for (let i = 0; i < taken.length; i++) {
                    if (at >= taken[i][0] && at < taken[i][1]) return true;
                }
                return false;
            };
            SPP_BARE_RE.lastIndex = 0;
            while ((m = SPP_BARE_RE.exec(src)) !== null) {
                const pos = m.index + m[1].length;          
                if (inTaken(pos)) continue;                 
                if (SPP_TLDS.indexOf(m[2].slice(m[2].lastIndexOf('.') + 1).toLowerCase()) < 0) continue;
                spans.push({
                    pos: pos,
                    
                    url: (m[2] + (m[3] || '')).replace(/[.,;:!?\u3001\u3002\uff0c\uff1b\uff1a]+$/, ''),
                });
            }
            if (!spans.length) { if (stats) { stats.none = 1; } return 0; }
            spans.sort(function (a, b) { return a.pos - b.pos; });
            const skip = { marked: 0, tag: 0, code: 0, attr: 0, self: 0 };
            const marks = [];                 
            let out = '', last = 0, adds = 0, rms = 0, wraps = 0;
            for (let i = 0; i < spans.length; i++) {
                const sp = spans[i];
                if (sp.pos < last) continue;
                out += src.slice(last, sp.pos);
                

                const cut = src.slice(0, sp.pos).replace(/[ \t\u3000]+$/, '');
                const name = markNameOf(sp.url);
                const tag = name ? '【' + name + '】' : '';
                const hasTag = !!name && cut.slice(-tag.length) === tag;
                



                const selfKind = sppSelfKind(sp.url);
                const isImg = selfKind === 'img' || sppImgLink(sp.url);
                const wantWrap = isImg && SELF_IMG;
                let why = '';
                if (!name && !wantWrap) why = 'n';                               
                else if (SPP_OPEN_TAG_RE.test(cut)) why = 'tag';                 
                else if (cut.lastIndexOf('[code]') > cut.lastIndexOf('[/code]')) why = 'code';
                else if (cut.lastIndexOf('<') > cut.lastIndexOf('>')) why = 'attr';   
                

                const staleTag = hasTag && isImg && !why;
                if (staleTag) {
                    out = out.slice(0, out.length - tag.length);
                    marks.push({ at: out.length, len: -tag.length });
                    rms++;
                    if (wantWrap) { marks.push({ at: out.length, len: 5 }); out += '[img]'; wraps++; }
                } else if (hasTag) {
                    skip.marked++;                                   
                } else if (why) {
                    if (why !== 'n') skip[why]++;
                } else if (selfKind === 'self' || (isImg && !wantWrap)) {
                    skip.self++;         
                } else if (wantWrap) {
                    
                    marks.push({ at: out.length, len: 5 });
                    out += '[img]';
                    wraps++;
                } else {
                    marks.push({ at: out.length, len: tag.length });
                    out += tag;
                    adds++;
                }
                out += src.slice(sp.pos, sp.pos + sp.url.length);
                if (wantWrap && !why) { marks.push({ at: out.length, len: 6 }); out += '[/img]'; }
                last = sp.pos + sp.url.length;
            }
            out += src.slice(last);
            if (stats) { stats.skip = skip; stats.removed = rms; stats.wrapped = wraps; }
            if (!adds && !rms && !wraps) return 0;
            const s = ta.selectionStart, e = ta.selectionEnd;
            ta.value = out;
            const shift = function (p) {
                let d = 0;
                for (let i = 0; i < marks.length; i++) { if (marks[i].at < p) d += marks[i].len; }
                return p + d;
            };
            try { ta.setSelectionRange(shift(s), shift(e)); } catch (err) { }
            return adds;
        }

        
        
        function openSite(url) {
            try { if (window.open(url, '_blank', 'noopener')) return; } catch (e) { }
            const a = document.createElement('a');
            a.href = url;
            a.target = '_blank';
            a.rel = 'noopener noreferrer';
            document.body.appendChild(a);
            a.click();
            a.parentNode.removeChild(a);
        }

        
        
        
        
