    const CSS_CARD = `
    .spp-cm-row > td { padding:14px 10px !important; border:none !important; background:transparent !important; }
    .spp-cm-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(330px,1fr)); gap:16px; }
    .spp-cm-grid.is-single { grid-template-columns:minmax(0,540px); justify-content:center; }
    /* 分组之间留出间距（CM 届次组 ↔ 常设大区组） */
    .spp-cm-grid + .spp-cm-grid { margin-top:16px; }
    /* 分组标题条：横跨整行，左右各一条细线，中间是标签与说明 */
    .spp-cm-group-hd {
        grid-column:1 / -1;
        display:flex; align-items:center; gap:10px;
        margin:2px 0 0; font-size:12px; letter-spacing:.02em;
        color:#94a3b8;
    }
    .spp-cm-group-hd::before, .spp-cm-group-hd::after {
        content:""; flex:1; height:1px; background:rgba(148,163,184,.22);
    }
    /* 第一组（紧随卡片行顶部）不加 before 线，避免多一条横线 */
    .spp-cm-group-hd.is-first::before { display:none; }
    .spp-cm-group-hd b { color:#cbd5e1; font-weight:650; font-size:12.5px; }
    .spp-cm-group-hd i { font-style:normal; color:#64748b; font-size:11px; }
    .spp-cm-group-hd em {
        font-style:normal; font-weight:600; font-size:10.5px;
        padding:2px 8px; border-radius:999px;
        background:rgba(56,126,240,.16); color:#93c5fd;
    }
    .spp-cm-group-hd.is-std em { background:rgba(255,34,136,.16); color:#f9a8d4; }
    .spp-cm-group-hd.is-pin em { background:rgba(12,227,154,.16); color:#6ee7b7; }

    .spp-cm-card {
        position:relative; padding:1.5px; border-radius:14px; overflow:hidden; isolation:isolate;
        background:#0b1120; cursor:pointer;
        /* 卡片是 grid item，会被拉伸到整行最高那张的高度。用 flex 列 + __inner:flex:1
           让内板填满，否则内容矮的卡（如只有 1 个子版入口的）底部会露出 ::before 渐变 */
        display:flex; flex-direction:column;
        box-shadow:0 18px 40px -18px rgba(2,6,23,.9);
        transition:transform .32s cubic-bezier(.2,.7,.3,1), box-shadow .32s ease;
        font-family:'Noto Sans SC','Source Han Sans SC','PingFang SC','Microsoft YaHei',sans-serif;
    }
    .spp-cm-card:hover { transform:translateY(-4px); box-shadow:0 26px 54px -20px rgba(99,102,241,.55); }

    .spp-cm-card__spin {
        position:absolute; top:50%; left:50%; width:120px; height:420px; margin:-210px 0 0 -60px;
        background:linear-gradient(180deg,#ff2288,#387ef0);
        opacity:0; z-index:0; pointer-events:none;
        animation:spp-cm-spin 8s linear infinite; animation-play-state:paused;
        transition:opacity .3s ease;
    }
    .spp-cm-card:hover .spp-cm-card__spin { opacity:1; animation-play-state:running; }
    @keyframes spp-cm-spin { from { transform:rotate(0deg); } to { transform:rotate(360deg); } }

    .spp-cm-card::before {
        content:""; position:absolute; inset:0; border-radius:14px; z-index:0;
        background:linear-gradient(120deg,rgba(56,126,240,.55),rgba(168,85,247,.4),rgba(255,34,136,.55));
        opacity:.45; transition:opacity .3s ease;
    }
    .spp-cm-card:hover::before { opacity:0; }

    .spp-cm-card__inner {
        position:relative; z-index:1; display:flex; flex-direction:column; gap:14px;
        flex:1 1 auto;   /* 撑满 .spp-cm-card，避免短卡底部露出 ::before 渐变 */
        padding:16px; border-radius:13px;
        background:linear-gradient(180deg,rgba(2,6,23,.97),rgba(2,6,23,.92));
        -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px);
    }

    /* ★★ 2.56.2（用户：「去除黄色框选（卡片顶部的文字，要适配移除黄色框选区域后的排版）」）：
       卡片顶部那枚 46×46 的渐变徽章不再渲染（见 buildCmCard）——「标题 + 状态胶囊」少了
       左边那位邻居，这一行改 center：标题与右侧胶囊竖向居中，不再是顶对齐、下面空一截。 */
    .spp-cm-card__head { display:flex; align-items:center; gap:10px; }
    /* ★★ 2.56.2：徽章那几条规则**留着不删**（回滚只需在 buildCmCard 里把注释揭开）；
       本轮起界面上不再有这枚「漫区 / 其他」的 46×46 渐变方块。 */
    .spp-cm-card__badge {
        flex:0 0 auto; display:flex; flex-direction:column; align-items:center; justify-content:center;
        width:46px; height:46px; border-radius:11px; line-height:1;
        background:linear-gradient(145deg,#387ef0,#a855f7);
        box-shadow:0 6px 16px -6px rgba(56,126,240,.8);
    }
    .spp-cm-card__badge em { font-style:normal; font-size:9px; font-weight:600; letter-spacing:.08em; opacity:.85; margin-bottom:3px; }
    .spp-cm-card__badge b { font-size:17px; font-weight:800; font-variant-numeric:tabular-nums; color:#fff; }

    /* ★★ 2.56.2：徽章撤掉后标题就是这一段的第一行，原先那 1px 补顶不再需要。 */
    .spp-cm-card__titles { flex:1 1 auto; min-width:0; display:flex; flex-direction:column; gap:5px; }
    .spp-cm-card__title {
        font-size:15px !important; font-weight:650 !important; color:#fff !important; text-decoration:none !important;
        white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    }
    .spp-cm-card__title:hover { color:#c7d2fe !important; }
    .spp-cm-card__meta { display:flex; flex-wrap:wrap; align-items:center; gap:2px 6px; font-size:11px; color:#64748b; }
    .spp-cm-card__meta b { color:#94a3b8; font-weight:600; font-variant-numeric:tabular-nums; }

    .spp-cm-card__pill {
        flex:0 0 auto; display:inline-flex; align-items:center; gap:5px; padding:3px 9px;
        border-radius:999px; font-size:10.5px; font-weight:600; white-space:nowrap;
        background:rgba(16,185,129,.12); color:#10b981;
    }
    .spp-cm-card__pill.is-idle { background:rgba(100,116,139,.16); color:#94a3b8; }
    .spp-cm-card__dot { width:6px; height:6px; border-radius:50%; background:currentColor; }
    .spp-cm-card__pill:not(.is-idle) .spp-cm-card__dot { animation:spp-cm-pulse 1.8s ease-in-out infinite; }
    @keyframes spp-cm-pulse { 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:.35; transform:scale(.8); } }

    .spp-cm-card__stats {
        display:grid; grid-template-columns:1fr 1fr 1.15fr; border-radius:10px; overflow:hidden;
        background:rgba(15,23,42,.6); border:1px solid rgba(148,163,184,.1);
    }
    .spp-cm-card__stat { display:flex; flex-direction:column; gap:2px; padding:9px 11px; position:relative; }
    .spp-cm-card__stat + .spp-cm-card__stat::before {
        content:""; position:absolute; left:0; top:18%; bottom:18%; width:1px; background:rgba(148,163,184,.14);
    }
    .spp-cm-card__stat .k { font-size:10.5px; color:#64748b; letter-spacing:.02em; }
    /* 数值栏：.v 一律不折行（数量级大的板块如「汉化本发布」2,588,429 会撑爆 72px 内容宽）；
       超过宽度时由 buildCmCard 给 .spp-cm-card__stats 挂 .is-wide 缩字号，
       而不是让数字断成两行 */
    .spp-cm-card__stat .v { font-size:16px; font-weight:700; color:#fff; font-variant-numeric:tabular-nums; letter-spacing:-.01em; white-space:nowrap; }
    .spp-cm-card__stats.is-wide .spp-cm-card__stat { padding:9px 8px; }
    .spp-cm-card__stats.is-wide .spp-cm-card__stat .v { font-size:13px; letter-spacing:-.02em; }
    .spp-cm-card__stat .v small { font-size:11px; font-weight:600; color:#94a3b8; margin-left:2px; }
    .spp-cm-card__stat .d { font-size:10px; color:#64748b; }
    .spp-cm-card__stat.is-hot .v { color:#10b981; }
    .spp-cm-card__stat.is-hot .d { color:#10b981; opacity:.75; }

    .spp-cm-card__boards { display:flex; flex-direction:column; gap:8px; }
    .spp-cm-card__boards-k { font-size:10.5px; color:#64748b; letter-spacing:.06em; display:flex; align-items:center; gap:8px; }
    .spp-cm-card__boards-k::after { content:""; flex:1; height:1px; background:rgba(148,163,184,.14); }

    .spp-cm-card__board {
        display:flex; align-items:center; gap:10px; padding:9px 11px; border-radius:10px;
        background:rgba(30,41,59,.5); border:1px solid rgba(148,163,184,.1); text-decoration:none !important;
        transition:background .18s ease,border-color .18s ease,transform .18s ease;
    }
    .spp-cm-card__board:hover { background:rgba(56,126,240,.16); border-color:rgba(56,126,240,.45); transform:translateX(2px); }
    .spp-cm-card__board-ico {
        flex:0 0 30px; width:30px; height:30px; border-radius:8px;
        display:flex; align-items:center; justify-content:center;
        background:rgba(56,126,240,.16); color:#93c5fd;
    }
    .spp-cm-card__board.is-wall .spp-cm-card__board-ico { background:rgba(255,34,136,.16); color:#f9a8d4; }
    .spp-cm-card__board-ico svg { width:15px; height:15px; }
    .spp-cm-card__board-txt { flex:1 1 auto; min-width:0; }
    .spp-cm-card__board-txt b { display:block; font-size:12.5px; font-weight:600; color:#e2e8f4; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .spp-cm-card__board-txt i { display:block; font-style:normal; font-size:10.5px; color:#64748b; margin-top:1px; }
    .spp-cm-card__board-go { flex:0 0 auto; color:#64748b; display:flex; }
    .spp-cm-card__board-go svg { width:13px; height:13px; }
    .spp-cm-card__board:hover .spp-cm-card__board-go { color:#c7d2fe; }

    .spp-cm-card__last {
        display:flex; align-items:center; gap:10px; padding:10px 11px; border-radius:10px;
        background:linear-gradient(90deg,rgba(56,126,240,.12),rgba(2,6,23,0));
        border-left:2px solid rgba(56,126,240,.6); text-decoration:none !important;
    }
    .spp-cm-card__last:hover { background:linear-gradient(90deg,rgba(56,126,240,.22),rgba(2,6,23,0)); }
    /* ★★ 2.56.2：最后发言行开头那枚「首字圆」不再渲染（用户圈的第二处黄框）——
       规则留着不删，回滚在 buildCmCard 里把注释揭开即可。 */
    .spp-cm-card__avatar {
        flex:0 0 26px; width:26px; height:26px; border-radius:50%;
        display:flex; align-items:center; justify-content:center;
        font-size:11px; font-weight:700; color:#fff;
        background:linear-gradient(145deg,#387ef0,#ff2288);
    }
    .spp-cm-card__last-txt { flex:1 1 auto; min-width:0; }
    .spp-cm-card__last-txt b { display:block; font-size:12px; font-weight:500; color:#dbe4f2; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .spp-cm-card__last-txt i { display:block; font-style:normal; font-size:10.5px; color:#64748b; margin-top:2px; }
    .spp-cm-card__last-time {
        flex:0 0 auto; display:flex; flex-direction:column; align-items:flex-end; gap:2px;
        font-size:10.5px; color:#94a3b8; font-variant-numeric:tabular-nums;
    }
    .spp-cm-card__last-time b { font-size:11px; color:#cbd5e1; font-weight:600; }
    .spp-cm-card__last-time.is-fresh b { color:#10b981; }

    /* margin-top:auto 把底部条推到卡片最下沿：同排卡片高度不一时（只有 1 个入口的短卡），
       按钮仍对齐在底部，而不是浮在内容后面留一片空白 */
    .spp-cm-card__foot { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:auto; padding-top:2px; }
    /* ★★ 2.56.2（用户：「对于绿色框选的进入板块，修改配色适配黑夜模式」）：
       原来那一对 #387ef0 → #a855f7 是两块高饱和亮色，白字对比只有 3.88:1 / 3.96:1
       （两头都不到 AA 的 4.5:1），压在深色卡上既抢眼又读不清。换成同族深两档：
       #2f5fd0（白字 5.72:1）→ #6d34c0（白字 7.23:1）；悬停只提一档亮度
       （brightness(1.06)，5.21:1 / 6.64:1），四个数都在 build 里现算断言。 */
    /* ★★ 2.56.4（用户任务 16③：「对于进入版块，修改为黑底白字」）：
       底色换纯黑、字纯白 —— 白字黑底 21:1，是这套配色里最高的一档（2.56.2 那对
       渐变压在深色卡上只有 5.72 / 7.23:1，本身没毛病，但用户要的是黑底白字）。
       ★ 这条 1px 描边是**必需**的，不是装饰：卡片内板底色是 rgba(2,6,23,.97)
       （≈#020617），纯黑压上去只有 1.04:1 —— 不加边整枚按钮会糊进卡里看不见。
       悬停也不再能用 filter（纯黑提亮等于没提）⇒ 底色抬到 #1a1a1a、描边提亮。 */
    .spp-cm-card__cta {
        flex:0 0 auto; display:inline-flex; align-items:center; gap:4px; padding:5px 11px; border-radius:8px;
        background:#000; border:1px solid rgba(255,255,255,.24); color:#fff !important;
        font-size:11px !important; font-weight:600 !important; text-decoration:none !important;
        transition:background .18s ease,border-color .18s ease;
    }
    .spp-cm-card__cta:hover { background:#1a1a1a; border-color:rgba(255,255,255,.42); }
    .spp-cm-card__cta svg { width:12px; height:12px; }

    .spp-cm-card__subs { display:flex; flex-wrap:wrap; gap:6px; min-width:0; }
    .spp-cm-card__subs a {
        font-size:10.5px !important; padding:3px 8px; border-radius:6px;
        background:rgba(51,65,85,.55); color:#cbd5e1 !important; text-decoration:none !important;
        transition:background .16s ease,color .16s ease;
    }
    .spp-cm-card__subs a:hover { background:rgba(99,102,241,.4); color:#fff !important; }

    /* ==================================================================
       渐变描边按钮 · 移植自 Uiverse / nima-mollazadeh (terrible-panda-97, MIT)
       机制：本体铺 45° 渐变，::before 用 inset:1px 的深色内板盖住中间 →
             只露出 1px 渐变边；hover 时内板半透明 + ::after 模糊辉光
       ================================================================== */
    .spp-uvbtn {
        position:relative !important; isolation:isolate;
        background:linear-gradient(45deg,#0ce39a,#69007f,#fc0987) !important;
        border:none !important; border-radius:11px !important;
        box-shadow:0 8px 22px -14px rgba(105,0,127,.85);
        overflow:visible;
    }
    .spp-uvbtn::before {
        content:""; position:absolute; inset:1px; border-radius:10px;
        background:#272727; z-index:-1; pointer-events:none;
        transition:opacity .5s ease;
    }
    .spp-uvbtn:hover::before { opacity:.72; }
    .spp-uvbtn::after {
        content:""; position:absolute; inset:0; border-radius:10px;
        background:linear-gradient(45deg,#0ce39a,#69007f,#fc0987);
        opacity:0; filter:blur(20px); z-index:-2; pointer-events:none;
        transition:opacity .5s ease;
    }
    .spp-uvbtn:hover::after { opacity:1; }
    .spp-uvbtn > * { position:relative; z-index:1; }

    /* 漫区特设 分类标题行套用上面的按钮样式（覆盖 CSS_BOARDS 里的浅色底） */
    html.spp-hm-on .t > table > tbody > tr > th.h.spp-uvbtn {
        background:linear-gradient(45deg,#0ce39a,#69007f,#fc0987) !important;
        border-bottom:none !important;
        padding:10px 14px !important;
    }
    .spp-hm-on .t > table > tbody > tr > th.h.spp-uvbtn h2 a.cfont {
        color:#fff !important; text-shadow:0 1px 6px rgba(0,0,0,.55);
    }
    .spp-hm-on .t > table > tbody > tr > th.h.spp-uvbtn h2 a.cfont::before {
        background:linear-gradient(180deg,#0ce39a,#fc0987) !important;
    }
    .spp-hm-on .t > table > tbody > tr > th.h.spp-uvbtn a.closeicon img { filter:invert(1); opacity:.7; }
    .spp-hm-on .t > table > tbody > tr > th.h.spp-uvbtn a.closeicon:hover img { opacity:1; }

    /* ==================================================================
       存档分区（旧物仓库）：独立标题条 + 子版小卡网格
       ================================================================== */
    .spp-cm-sec { display:flex; flex-direction:column; gap:14px; }
    .spp-cm-sec__hd {
        display:flex; align-items:center; gap:12px; padding:11px 16px; flex-wrap:wrap;
    }
    .spp-cm-sec__bar {
        width:3px; height:15px; border-radius:2px; flex:0 0 auto;
        background:linear-gradient(180deg,#0ce39a,#fc0987);
    }
    .spp-cm-sec__title {
        font-size:14.5px !important; font-weight:700 !important;
        color:#fff !important; text-decoration:none !important;
        text-shadow:0 1px 6px rgba(0,0,0,.55);
    }
    .spp-cm-sec__title:hover { color:#a7f3d0 !important; }
    .spp-cm-sec__meta {
        font-size:11.5px; color:#cbd5e1; font-variant-numeric:tabular-nums;
    }
    .spp-cm-sec__count {
        margin-left:auto; font-size:11px; font-weight:600; padding:3px 10px; border-radius:999px;
        background:rgba(12,227,154,.14); color:#6ee7b7;
    }

    .spp-cm-sec__grid {
        display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:10px;
    }
    .spp-cm-mini {
        position:relative; display:flex; align-items:center; padding:10px 14px 10px 16px;
        border-radius:10px; overflow:hidden;
        /* 芯片直接坐在论坛的浅色内容区（#fafcff）上，底色必须不透明 ——
           否则半透明深色会被浅底冲成中灰，和深色预览页对不上 */
        background:#141d2f; border:1px solid rgba(148,163,184,.24);
        text-decoration:none !important;
        transition:border-color .18s ease, background .18s ease, transform .18s ease;
    }
    .spp-cm-mini::before {
        content:""; position:absolute; left:0; top:0; bottom:0; width:3px;
        background:linear-gradient(180deg,#0ce39a,#69007f,#fc0987);
        opacity:.8; transition:opacity .18s ease;
    }
    .spp-cm-mini:hover {
        background:#1d2a44; border-color:rgba(12,227,154,.55); transform:translateY(-2px);
    }
    .spp-cm-mini:hover::before { opacity:1; }
    .spp-cm-mini__nm {
        font-size:13px; font-weight:600; color:#e2e8f4; letter-spacing:.01em;
        white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    }

    /* ==================================================================
       友情链接卡片 · 移植自 uiverse.io/gharsh11032000/tasty-frog-49
       Copyright - 2026 gharsh11032000 (Harsh Gupta) — MIT License
       机制：本体深色底；::before 铺 45° 渐变、比本体大 5px 一圈 → 只露出渐变边；
             hover 时该渐变块旋转 90° 并拉伸；::after 同色系模糊块，hover 时
             blur 20→30px 形成外发光。
       ★ 本体不能设 isolation / overflow:hidden —— ::before 用 z-index:-10，
         一裁就只剩普通描边方块、动效全丢。
       ★★ hover 变换的 scaleX/scaleY 必须按实测尺寸算，不能照抄原版的 1.34/0.77：
          原版卡 190×254，::before 为 inset:-5px 后约 200×264。rotate(-90deg) 会把
          宽高对调，所以要先压宽、拉高，旋转后才回到「与卡片同形」。反算公式：
              sy = k·卡宽/(卡高+10) ，sx = k·卡高/(卡宽+10) ，k = 1.06
          代回原版 (190,254)：sx = 1.346 / sy = 0.763 —— 正是原版的 1.34 / 0.77（误差<1%），
          说明这就是原作者当初的算法。而我们的横版面板代进去是 sx≈0.49 / sy≈2.19；
          若照抄 1.34/0.77，旋转后会得到 292×1061 的竖长条、溢出整屏（已实测复现）。
          数值由 syncFriendCardScale() 写入 --spp-fl-sx / --spp-fl-sy。
       ★★ 2.56.3（用户：「BUG：经典滚动条溢出」）：上面那套「旋转 + 拉伸」的悬停动效
          会把装饰推到卡片之外最多 22px（横向 6%）/ 11px（纵向 6%），::after 的模糊
          半径还会在悬停时从 20px 加到 30px（光晕再多探约 15px）—— 面板本来就贴着页面
          底部时，鼠标一移上去就会多出一条滚动条（经典那条），滚动条一出现又挤掉十几像素、
          整页跟着抖一下。2.56.3 起悬停**一个像素的几何都不改**：渐变边改 opacity 淡入
          （框恒为 inset:-5px、不再旋转也不缩放），模糊半径恒 20px。
          ★ --spp-fl-sx / --spp-fl-sy 与 syncFriendCardScale() 一并留着（现在没有规则读它们，
            回滚就是把上面那条 hover::before 换回 rotate+scale）。
       ================================================================== */
    .spp-fl-card {
        position:relative; background:#0b0f1a; border-radius:8px; cursor:default;
        display:flex; flex-direction:column; gap:12px; padding:14px 16px 16px;
    }
    /* ★★ 2.56.3：这一层从出生起就待在自己的合成层上（translateZ(0)），可见性只由
       opacity 管 —— 不再靠悬停时的一次 transform 才"现形"（以前它在静止态显不显示，
       取决于浏览器把这层排到祖先底色之上还是之下；现在两台机器上都一样：静止不显示、
       悬停淡入）。框恒定 inset:-5px ⇒ 悬停前后绘制范围完全一致，不会因为移一下鼠标
       就把页面顶出滚动条。 */
    .spp-fl-card::before {
        content:''; position:absolute; inset:-5px; border-radius:10px;
        background:linear-gradient(-45deg,#e81cff 0%,#40c9ff 100%);
        z-index:-10; pointer-events:none;
        opacity:0; transform:translateZ(0);
        transition:opacity .45s cubic-bezier(.175,.885,.32,1.275);
    }
    .spp-fl-card::after {
        content:""; position:absolute; inset:0; border-radius:8px;
        background:linear-gradient(-45deg,#fc00ff 0%,#00dbde 100%);
        transform:translate3d(0,0,0) scale(.95); filter:blur(20px);
        z-index:-1;
    }
    /* ★★ 2.56.3：原来这里在悬停时把模糊从 20px 加到 30px —— 光晕因此再多探出去约 15px，
       正是「鼠标一移上去就多一条滚动条」的第二半原因。现在半径恒定 20px（下面 ::after 里那条），
       这条整条撤掉。 */
    /* ★★ 2.56.2（用户：「鼠标移动到框选部分后会有一个BUG」）：
       原来是 rotate(-90deg) + 两轴不等比 scale（sx/sy 由卡片长宽现算，本机实测
       0.5289 / 2.0403）。旋转 + 不等比缩放会把 inset:-5px 的这圈渐变**从「边框」
       拉成一条横贯卡片的长带**扫过去；而这层伪元素是 z-index:-10、又靠 transform
       才拿到自己的合成层 ⇒ 它压在卡片底之下还是之上由浏览器定，所以同一个效果在
       两台机器上表现不一样（他那台看得见那抹扫过的带子，我这台扫不动）。
       改等比 1.012：悬停时照样给自己开一层合成层（边框仍旧只在悬停时出现，手感没丢），
       但整层不旋转、不被拉长 —— 不会再有色带扫出来。
       ★ --spp-fl-sx / --spp-fl-sy 与 syncFriendCardScale 一起留着（现在没有规则读它们，
         回滚就是把上面那行放回来）。 */
    .spp-fl-card:hover::before {
        opacity:1;
    }

    .spp-fl-head { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
    .spp-fl-head .ttl { font-size:20px; font-weight:700; color:#fff; letter-spacing:.01em; }
    .spp-fl-head .cnt {
        font-size:11px; font-weight:600; padding:2px 9px; border-radius:999px;
        background:rgba(232,28,255,.16); color:#f0abfc;
    }
    .spp-fl-head .hint { font-size:11.5px; color:#64748b; margin-left:auto; }

    /* 网格列数：紧凑 142px / 舒适 196px */
    .spp-fl-grid { display:grid; gap:7px; grid-template-columns:repeat(auto-fill,minmax(142px,1fr)); }
    .spp-fl-card.is-loose .spp-fl-grid { gap:10px; grid-template-columns:repeat(auto-fill,minmax(196px,1fr)); }

    .spp-fl-item {
        display:flex; align-items:center; gap:9px; text-decoration:none !important;
        padding:9px 11px; border-radius:9px; min-width:0;
        background:rgba(30,41,59,.55); border:1px solid rgba(148,163,184,.12);
        transition:background .18s ease, border-color .18s ease, transform .18s ease;
    }
    .spp-fl-item:hover {
        background:rgba(232,28,255,.14); border-color:rgba(232,28,255,.45);
        transform:translateY(-2px);
    }
    .spp-fl-dot {
        flex:0 0 auto; width:24px; height:24px; border-radius:7px;
        display:grid; place-items:center; font-size:11px; font-weight:800; color:#fff;
        background:linear-gradient(145deg,#e81cff,#40c9ff);
        box-shadow:0 4px 12px -5px rgba(232,28,255,.8);
    }
    .spp-fl-txt { min-width:0; display:flex; flex-direction:column; gap:1px; }
    .spp-fl-txt b {
        font-size:12.5px; font-weight:600; color:#fff;
        white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    }
    .spp-fl-txt i {
        font-style:normal; font-size:10.5px; color:#64748b;
        white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    }
    .spp-fl-item:hover .spp-fl-txt i { color:#a5b4fc; }

    /* .spp-fl-foot（卡片底下的uiverse署名脚注）在 2.52.97 随那段文本一起删除 —— 界面要干净，
       MIT 声明留在注释里（见 CSS 段头与 buildFriendCard 上方）。 */

    /* 方案A：人民囧府区块内两栏。
       align-items:stretch 让右栏友链卡与左栏事务卡底边对齐
       （实测 782×369 时两卡等高 369px；用 start 会错开一条边）。
       .spp-cm-card__inner 自带 flex:1，能自然吃下多出的高度。 */
    .spp-fl-two { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1.15fr); gap:16px; align-items:stretch; }
    .spp-fl-two > * { min-width:0; }
    .spp-fl-two > .spp-cm-grid { display:flex; flex-direction:column; }
    .spp-fl-two > .spp-cm-grid > .spp-cm-card { flex:1 1 auto; }
    @media (max-width:1000px) { .spp-fl-two { grid-template-columns:minmax(0,1fr); } }
    /* ★ 站点全局 CSS 给 .t 加了 overflow:hidden!important（见 CSS_BASE 里的
       「.t,.t5,table.t_one{…overflow:hidden!important…}」那条），会把 ::before 那圈
       渐变与 ::after 的辉光在卡片边缘裁掉。这两条把它放开（仅友链卡所在宿主）。 */
    .spp-hm-on .t.spp-fl-host, .spp-hm-on .t.spp-fl-host > table,
    .spp-hm-on .t.spp-fl-host > table > tbody,
    .spp-hm-on .t.spp-fl-host > table > tbody > tr,
    .spp-hm-on .t.spp-fl-host > table > tbody > tr > td { overflow:visible !important; }
    /* ==================== 2.57.59 段头（CSS 侧）====================
       这一整段是「存档分区（旧物仓库）·数据星系」的新版，替换掉 2.57.41~2.57.43
       那一版（旧段：核 102px、三条虚线轨道 + 26 枚药丸、没有 HUD / 弹窗）。
       视觉与交互照抄参考稿 gemini参考/星系图-gemini-code-1791698833226.html，
       只把「整页 demo 的外壳」剔掉，并做三处必需改动：
         ① 参考稿写 :root 的 10 个变量收进 .spp-gal-wrap / .spp-modal-backdrop：
            原先挂在根元素上 = 给全站加一批自定义属性，没必要；
            --spp-gal-core（核直径）也从 122px 这里唯一一处给。
         ② 参考稿的 「*{box-sizing:border-box}」 改成只在本节容器内生效：
            直接搬会改掉站点全站的盒子模型（整站排版会跟着动）。
         ③ 参考稿的 html,body{…} 不搬（底色 / 字体 / overflow 归站点主题管）；
            #spp-starfield 与 @keyframes spp-star-move 不搬（站点星空本来就是同一套）；
            .spp-nebula 星云层不搬 —— 用户 ⑤「这个背景和网址的背景是一样的，
            不需要再弄一个背景了」；.spp-scene / .spp-host 外壳也不搬（这块坐在 #t_39 里）。
       ★ 参考稿自带一层深色板底（.spp-gal 的 radial-gradient + 24px 圆角 + 描边 + 内阴影）：
         这一版照抄了。若想让它像 2.57.43 那样「直接坐在站点星空上」，
         删 .spp-gal 里的 background / border / box-shadow 三行即可。
       ★ 核直径只由 --spp-gal-core 给（122px，≤860px 视口时 104px），想调只改那两处。
       ★ 怎么退：把本段整块换回 2.57.58 的 .spp-gal-wrap/.spp-cm-group-hd 那一段 */
    .spp-gal-wrap, .spp-gal-wrap *, .spp-gal-wrap *::before, .spp-gal-wrap *::after,
    .spp-modal-backdrop, .spp-modal-backdrop * { box-sizing:border-box; }

    .spp-gal-wrap, .spp-modal-backdrop {
        --spp-gal-core: 122px;
        --c-cyan:#00eeff; --c-purple:#aa00ff; --c-pink:#ff007f; --c-gold:#fbbf24;
        --glow-cyan:rgba(0,238,255,.45); --glow-pink:rgba(255,0,127,.45);
        --glow-purple:rgba(170,0,255,.45); --glow-gold:rgba(251,191,36,.6);
        --bg-dark:#060811;
    }
    .spp-gal-wrap {
        display:flex; flex-direction:column; gap:14px;
        font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Noto Sans SC','Source Han Sans SC','PingFang SC','Microsoft YaHei',sans-serif;
    }
    /* ↓↓↓ 以下照抄参考稿（78~616 行），只把每行缩进补成 4 空格 ↓↓↓ */

    .spp-hud-bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        flex-wrap: wrap;
        gap: 12px;
        padding: 12px 22px;
        background: rgba(13, 17, 30, 0.72);
        backdrop-filter: blur(16px);
        -webkit-backdrop-filter: blur(16px);
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 16px;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.08);
    }

    .spp-hud-left {
        display: flex;
        align-items: center;
        gap: 12px;
        flex-wrap: wrap;
    }

    .spp-hud-title {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        font-size: 14px;
        font-weight: 700;
        color: #f8fafc !important;
        text-decoration: none !important;
        letter-spacing: 0.04em;
        transition: all 0.25s ease;
    }
    .spp-hud-title:hover {
        color: var(--c-cyan) !important;
        text-shadow: 0 0 14px var(--c-cyan);
    }
    .spp-hud-title svg { color: var(--c-cyan); filter: drop-shadow(0 0 6px var(--c-cyan)); }

    .spp-badge {
        font-size: 11px;
        font-weight: 600;
        padding: 3px 10px;
        border-radius: 999px;
        line-height: 1.3;
        display: inline-flex;
        align-items: center;
        gap: 5px;
        border: 1px solid transparent;
    }
    .spp-badge-mint {
        background: rgba(16, 185, 129, 0.15);
        color: #6ee7b7;
        border-color: rgba(16, 185, 129, 0.35);
    }
    .spp-badge-gold {
        background: rgba(251, 191, 36, 0.15);
        color: #fbbf24;
        border-color: rgba(251, 191, 36, 0.4);
        box-shadow: 0 0 10px rgba(251, 191, 36, 0.2);
    }

    .spp-hud-stats {
        display: inline-flex;
        align-items: center;
        gap: 14px;
        color: #94a3b8;
        font-size: 12px;
        margin-left: 6px;
    }
    .spp-hud-stat-item {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        font-variant-numeric: tabular-nums;
    }
    .spp-hud-stat-item svg { opacity: 0.85; }

    .spp-hud-right {
        display: flex;
        align-items: center;
        gap: 14px;
    }

    .spp-filter-group {
        display: inline-flex;
        background: rgba(0, 0, 0, 0.4);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 10px;
        padding: 3px;
        gap: 2px;
    }
    .spp-filter-btn {
        background: transparent;
        border: none;
        color: #94a3b8;
        font-size: 11.5px;
        font-weight: 600;
        padding: 4px 11px;
        border-radius: 7px;
        cursor: pointer;
        transition: all 0.2s ease;
    }
    .spp-filter-btn:hover { color: #f1f5f9; }
    .spp-filter-btn.active {
        background: rgba(0, 238, 255, 0.18);
        color: var(--c-cyan);
        box-shadow: 0 0 12px rgba(0, 238, 255, 0.28);
    }
    .spp-filter-btn[data-filter="milestone"].active {
        background: rgba(251, 191, 36, 0.2);
        color: #fbbf24;
        box-shadow: 0 0 12px rgba(251, 191, 36, 0.35);
    }

    .spp-live-status {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-family: ui-monospace, Menlo, Consolas, monospace;
        font-size: 11px;
        letter-spacing: 0.14em;
        color: rgba(74, 222, 128, 0.95);
        padding: 3px 9px;
        border-radius: 6px;
        background: rgba(74, 222, 128, 0.09);
    }
    .spp-live-dot {
        width: 6px; height: 6px; border-radius: 50%;
        background: #4ade80; box-shadow: 0 0 8px #4ade80;
        animation: spp-pulse-glow 1.8s ease-in-out infinite alternate;
    }
    @keyframes spp-pulse-glow {
        from { opacity: 0.35; transform: scale(0.9); }
        to { opacity: 1; transform: scale(1.15); box-shadow: 0 0 12px #4ade80; }
    }

    /* ==================================================================
       2. 星系舞台、轨道线与节点 (药丸)
       ================================================================== */
    .spp-gal {
        position: relative;
        overflow: hidden;
        height: clamp(500px, 49vw, 720px);
        border-radius: 24px;
        background: radial-gradient(circle at 50% 50%, rgba(15, 23, 42, 0.52) 0%, rgba(5, 7, 15, 0.85) 85%);
        border: 1px solid rgba(255, 255, 255, 0.08);
        box-shadow: 0 25px 60px rgba(0, 0, 0, 0.65), inset 0 0 70px rgba(0, 0, 0, 0.85);
        isolation: isolate;
    }

    .spp-gal__stage { position: absolute; inset: 0; z-index: 10; }

    /* 轨道虚线与引力光圈 */
    .spp-gal__ring {
        position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
        border: 1px dashed rgba(255, 255, 255, 0.075);
        border-radius: 50%;
        pointer-events: none; z-index: 1;
        transition: border-color 0.4s ease;
    }
    .spp-gal__ring::after {
        content: '';
        position: absolute; inset: -1px; border-radius: 50%;
        box-shadow: inset 0 0 16px rgba(255, 255, 255, 0.02);
        pointer-events: none;
    }

    /* 动态激光引力牵引线 (SVG) */
    #spp-gal-tether-svg {
        position: absolute; inset: 0; width: 100%; height: 100%;
        pointer-events: none; z-index: 25;
    }

    /* 节点 (会场药丸芯片) */
    .spp-gal__node {
        --gal-c: rgb(0, 238, 255);
        --gal-glow: 0 0 12px rgba(0, 238, 255, 0.25);
        position: absolute; left: 50%; top: 50%;
        width: 86px; height: 38px;
        border-radius: 999px;
        display: inline-flex; align-items: center; justify-content: center;
        font-size: 13.5px; font-weight: 750; letter-spacing: 0.06em; line-height: 1;
        background: rgba(10, 14, 28, 0.82);
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);
        border: 1.5px solid var(--gal-c) !important;
        color: var(--gal-c) !important;
        box-shadow: var(--gal-glow), inset 0 0 8px rgba(0, 0, 0, 0.5) !important;
        text-decoration: none !important;
        cursor: pointer;
        user-select: none;
        will-change: transform, opacity;
        transition: color 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
    }

    /* 历史重要节点黄金/皇冠微徽标 */
    .spp-gal__node[data-name="C107"]::after,
    .spp-gal__node[data-name="C100"]::after {
        content: '👑';
        position: absolute; top: -8px; right: -5px;
        font-size: 11px; line-height: 1;
        filter: drop-shadow(0 0 6px var(--c-gold));
    }
    .spp-gal__node[data-name="C108"]::after,
    .spp-gal__node[data-name="C97"]::after,
    .spp-gal__node[data-name="C98"]::after {
        content: '★';
        position: absolute; top: -6px; right: -4px;
        font-size: 10px; width: 14px; height: 14px;
        border-radius: 50%; display: flex; align-items: center; justify-content: center;
        background: var(--c-gold); color: #000;
        box-shadow: 0 0 8px var(--c-gold);
    }

    /* 激活聚焦状态 */
    .spp-gal__node.is-active {
        background: #ffffff !important;
        color: #050814 !important;
        border-color: #ffffff !important;
        box-shadow: 0 0 25px #ffffff, 0 0 50px var(--gal-c) !important;
        transform-origin: center center;
        font-weight: 850;
    }

    /* ==================================================================
       3. 高维核心天体（黑洞、吸积盘与动态历史控制中枢）
       ================================================================== */
    .spp-core-anchor {
        position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
        width: var(--spp-gal-core); height: var(--spp-gal-core);
        z-index: 60;
        pointer-events: auto;
    }

    /* 外层引力吸积盘 (Accretion Disk) */
    .spp-accretion-disk {
        position: absolute; inset: -28px;
        border-radius: 50%;
        background: conic-gradient(
            from 0deg,
            rgba(0, 238, 255, 0.45),
            rgba(170, 0, 255, 0.55),
            rgba(255, 0, 127, 0.65),
            rgba(251, 191, 36, 0.4),
            rgba(0, 238, 255, 0.45)
        );
        filter: blur(15px);
        opacity: 0.7;
        animation: spp-disk-spin 12s linear infinite;
        transition: opacity 0.4s ease, filter 0.4s ease;
        pointer-events: none;
    }
    @keyframes spp-disk-spin {
        from { transform: rotate(0deg); }
        to { transform: rotate(360deg); }
    }

    /* 黑洞视界本体 */
    .spp-blackhole-body {
        position: absolute; inset: 0;
        border-radius: 50%;
        background: radial-gradient(circle at 40% 40%, #0d121f 0%, #000000 70%);
        border: 1.5px solid rgba(255, 255, 255, 0.22);
        box-shadow: 
            0 0 26px rgba(255, 0, 127, 0.38),
            0 0 54px rgba(0, 238, 255, 0.32),
            inset 0 0 22px rgba(0, 0, 0, 0.95);
        cursor: pointer;
        overflow: hidden;
        display: flex; flex-direction: column; align-items: center; justify-content: center;
        transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.35s ease;
    }
    .spp-blackhole-body:hover {
        transform: scale(1.08);
        box-shadow: 
            0 0 38px rgba(255, 0, 127, 0.65),
            0 0 75px rgba(0, 238, 255, 0.55),
            inset 0 0 26px rgba(0, 0, 0, 0.95);
    }

    /* 核心事件视界流光弧线 */
    .spp-event-horizon {
        position: absolute; inset: 2px; border-radius: 50%;
        border: 1px solid transparent;
        border-top: 2px solid rgba(0, 238, 255, 0.85);
        border-bottom: 2px solid rgba(255, 0, 127, 0.85);
        animation: spp-horizon-rotate 6s ease-in-out infinite alternate;
        pointer-events: none;
    }
    @keyframes spp-horizon-rotate {
        from { transform: rotate(0deg) scale(0.96); opacity: 0.65; }
        to   { transform: rotate(180deg) scale(1.03); opacity: 1; }
    }

    /* 黑洞内默认空寂态 UI */
    .spp-core-idle {
        display: flex; flex-direction: column; align-items: center; justify-content: center;
        gap: 4px; pointer-events: none; transition: opacity 0.3s ease;
    }
    .spp-core-idle-icon {
        width: 22px; height: 22px; color: rgba(255, 255, 255, 0.75);
        filter: drop-shadow(0 0 8px rgba(0, 238, 255, 0.85));
        animation: spp-float 3s ease-in-out infinite alternate;
    }
    .spp-core-idle-txt {
        font-size: 10px; font-weight: 700; color: #cbd5e1;
        letter-spacing: 0.12em; text-transform: uppercase;
        text-shadow: 0 0 8px rgba(255, 255, 255, 0.4);
    }
    @keyframes spp-float {
        from { transform: translateY(-2px); }
        to { transform: translateY(2px); }
    }

    /* 黑洞被行星击中/选中后的活跃全息 HUD 控制台 */
    .spp-core-active-hud {
        position: absolute; inset: 0;
        display: none; flex-direction: column; align-items: center; justify-content: center;
        padding: 8px; text-align: center;
        background: radial-gradient(circle, rgba(16, 24, 48, 0.94) 0%, rgba(5, 7, 15, 0.97) 100%);
        /* ★ 2.57.62：出现时也不许动 —— 只淡入，transform 一律不碰。参考稿是
           scale(0.75)→1 ＋ 回弹缓动（26% 的缩放，比弹窗那一下还猛）。
           名字保持 spp-core-pop 不改：本项目踩过 @keyframes 重名的坑，改名要先把
           全文搜一遍；这里只换内容，名字仍唯一。
           要回参考稿：animation: spp-core-pop 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275); */
        animation: spp-core-pop 0.2s ease-out;
    }
    .spp-core-active-hud.show { display: flex; }
    @keyframes spp-core-pop {
        from { opacity: 0; }
        to   { opacity: 1; }
    }

    .spp-core-target-name {
        font-size: 16px; font-weight: 900; letter-spacing: 0.05em;
        background: linear-gradient(135deg, #ffffff 20%, var(--c-cyan) 80%);
        -webkit-background-clip: text; -webkit-text-fill-color: transparent;
        line-height: 1.1; margin-bottom: 2px;
    }
    .spp-core-open-badge {
        display: inline-flex; align-items: center; gap: 3px;
        font-size: 9.5px; font-weight: 700;
        padding: 2px 7px; border-radius: 999px;
        background: rgba(0, 238, 255, 0.22);
        color: var(--c-cyan);
        border: 1px solid rgba(0, 238, 255, 0.45);
        box-shadow: 0 0 10px rgba(0, 238, 255, 0.3);
        margin-bottom: 4px;
        /* ★ 2.57.62：这枚「点击查阅档案」徽章原先挂着 spp-pulse-glow 1.5s infinite
           alternate —— 那是**永远在动**的（scale 0.9↔1.15 ＋ 明暗呼吸，1.5 秒一个
           来回）。用户要求它别动，整条撤掉；徽章自己的静态光晕（上面那行 box-shadow）
           留着。那组 keyframes 不能删 —— 同一个名字还被右下角 ONLINE 小绿点用着
           （.spp-live-dot，1.8s）。要回参考稿原样：把
               animation: spp-pulse-glow 1.5s infinite alternate;
           加回 margin-bottom 那行下面。 */
    }
    .spp-core-sub-action {
        display: inline-flex; align-items: center; gap: 3px;
        font-size: 9px; color: #94a3b8; text-decoration: none;
        transition: color 0.2s ease;
    }
    .spp-core-sub-action:hover { color: #f8fafc; }

    /* 黑洞底边能量条 */
    .spp-gal__line {
        position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%);
        width: 44px; height: 1.5px; opacity: 0.7;
        background: linear-gradient(90deg, transparent, rgba(255, 0, 127, 0.95), transparent);
        pointer-events: none;
    }

    /* ==================================================================
       4. 引力弹窗：时空档案全息阅读器 (Modal)
       ================================================================== */
    .spp-modal-backdrop {
        position: fixed; inset: 0; z-index: 9999;
        background: rgba(3, 5, 12, 0.8);
        backdrop-filter: blur(20px);
        -webkit-backdrop-filter: blur(20px);
        display: flex; align-items: center; justify-content: center;
        padding: 20px;
        opacity: 0; pointer-events: none;
        transition: opacity 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .spp-modal-backdrop.open {
        opacity: 1; pointer-events: auto;
    }

    .spp-modal-dialog {
        width: min(800px, 94vw);
        max-height: 88vh;
        display: flex; flex-direction: column;
        background: linear-gradient(145deg, rgba(20, 27, 45, 0.93) 0%, rgba(10, 14, 26, 0.97) 100%);
        border: 1px solid rgba(255, 255, 255, 0.15);
        border-radius: 24px;
        box-shadow: 
            0 25px 75px rgba(0, 0, 0, 0.85),
            0 0 45px rgba(0, 238, 255, 0.16),
            inset 0 1px 0 rgba(255, 255, 255, 0.22);
        overflow: hidden;
        /* ★ 2.57.61：用户嫌这一下缩放太猛。参考稿是 scale(0.92)→1（8% 缩放）＋
           translateY(20px) ＋ cubic-bezier(.34,1.56,.64,1) —— 这个缓动带回弹：
           进度在 57% 处冲到 1.0978，映射到 scale 就是峰值 1.0078，一次点击合计
           约 8.8% 的缩放 ＋ 20px 的位移。改成 0.99→1（1%）＋ 6px ＋ 普通缓出
           （峰值正好 1，不回弹）⇒ 缩放收敛到约 1/8.8、位移约 1/3.3。
           要回参考稿原样：把下面两行换回
               transform: scale(0.92) translateY(20px);
               transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); */
        transform: scale(0.99) translateY(6px);
        transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .spp-modal-backdrop.open .spp-modal-dialog {
        transform: scale(1) translateY(0);
    }

    /* 弹窗头部 */
    .spp-modal-header {
        padding: 20px 24px;
        background: rgba(255, 255, 255, 0.03);
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
        display: flex; align-items: center; justify-content: space-between;
        position: relative;
    }
    .spp-modal-header-left {
        display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
    }
    .spp-modal-title {
        font-size: 28px; font-weight: 900; letter-spacing: 0.04em;
        color: #ffffff; line-height: 1;
    }
    .spp-modal-season-tag {
        font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px;
    }
    .tag-summer {
        background: rgba(251, 191, 36, 0.16); color: #fbbf24; border: 1px solid rgba(251, 191, 36, 0.4);
    }
    .tag-winter {
        background: rgba(0, 238, 255, 0.16); color: #38bdf8; border: 1px solid rgba(0, 238, 255, 0.4);
    }
    .tag-special {
        background: rgba(255, 0, 127, 0.18); color: #f43f5e; border: 1px solid rgba(255, 0, 127, 0.4);
    }
    .tag-anniv {
        background: linear-gradient(135deg, rgba(251, 191, 36, 0.25), rgba(255, 0, 127, 0.25));
        color: #fde047; border: 1px solid rgba(251, 191, 36, 0.5);
        box-shadow: 0 0 12px rgba(251, 191, 36, 0.3);
    }

    .spp-modal-date {
        font-size: 13px; color: #94a3b8; font-variant-numeric: tabular-nums;
    }

    .spp-modal-close {
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid rgba(255, 255, 255, 0.1);
        color: #94a3b8;
        width: 34px; height: 34px; border-radius: 50%;
        display: flex; align-items: center; justify-content: center;
        cursor: pointer; transition: all 0.2s ease;
    }
    .spp-modal-close:hover {
        background: rgba(255, 0, 127, 0.25);
        color: #ffffff; border-color: rgba(255, 0, 127, 0.5);
        transform: rotate(90deg);
    }

    /* 弹窗内容卷轴 */
    .spp-modal-body {
        padding: 24px;
        overflow-y: auto;
        display: flex; flex-direction: column; gap: 20px;
    }
    .spp-modal-body::-webkit-scrollbar { width: 6px; }
    .spp-modal-body::-webkit-scrollbar-thumb {
        background: rgba(255, 255, 255, 0.15); border-radius: 999px;
    }

    /* 信息区块卡片 */
    .spp-info-card {
        background: rgba(255, 255, 255, 0.025);
        border: 1px solid rgba(255, 255, 255, 0.07);
        border-radius: 14px;
        padding: 16px 18px;
    }
    .spp-info-card-title {
        display: flex; align-items: center; gap: 8px;
        font-size: 13px; font-weight: 750; color: #38bdf8;
        letter-spacing: 0.05em; text-transform: uppercase;
        margin-bottom: 12px;
    }
    .spp-info-card-title svg { width: 15px; height: 15px; }

    .spp-tag-cloud {
        display: flex; flex-wrap: wrap; gap: 8px;
    }
    .spp-ip-pill {
        font-size: 12px; font-weight: 600;
        padding: 5px 12px; border-radius: 8px;
        background: rgba(170, 0, 255, 0.12);
        color: #d8b4fe; border: 1px solid rgba(170, 0, 255, 0.25);
    }

    .spp-history-list {
        margin: 0; padding-left: 20px;
        display: flex; flex-direction: column; gap: 10px;
        color: #cbd5e1; font-size: 13.5px; line-height: 1.68;
    }
    .spp-history-list li strong { color: #f8fafc; font-weight: 700; }

    /* 弹窗底部操作条 (含原版跳转) */
    .spp-modal-footer {
        padding: 16px 24px;
        background: rgba(255, 255, 255, 0.02);
        border-top: 1px solid rgba(255, 255, 255, 0.07);
        display: flex; align-items: center; justify-content: space-between;
        flex-wrap: wrap; gap: 12px;
    }
    .spp-modal-nav-group {
        display: flex; align-items: center; gap: 8px;
    }
    .spp-nav-pill-btn {
        background: rgba(255, 255, 255, 0.05);
        border: 1px solid rgba(255, 255, 255, 0.1);
        color: #cbd5e1;
        font-size: 12px; font-weight: 600;
        padding: 7px 14px; border-radius: 8px;
        cursor: pointer; transition: all 0.2s ease;
        display: inline-flex; align-items: center; gap: 4px;
    }
    .spp-nav-pill-btn:hover:not(:disabled) {
        background: rgba(0, 238, 255, 0.15);
        color: var(--c-cyan); border-color: rgba(0, 238, 255, 0.4);
    }
    .spp-nav-pill-btn:disabled {
        opacity: 0.35; cursor: not-allowed;
    }

    .spp-direct-jump-btn {
        display: inline-flex; align-items: center; gap: 6px;
        background: linear-gradient(135deg, #00eeff, #0284c7);
        color: #030712 !important;
        font-size: 13px; font-weight: 750;
        padding: 8px 18px; border-radius: 10px;
        text-decoration: none !important;
        box-shadow: 0 4px 18px rgba(0, 238, 255, 0.35);
        transition: all 0.25s ease;
    }
    .spp-direct-jump-btn:hover {
        transform: translateY(-1px);
        box-shadow: 0 6px 25px rgba(0, 238, 255, 0.55);
        filter: brightness(1.1);
    }

    /* ==================================================================
       5. 响应式布局优化
       ================================================================== */
    /* ↓↓↓ 参考稿的响应式段（617~625 行）：只有 :root 那条改成 .spp-gal-wrap ↓↓↓ */
    @media (max-width: 860px) {
        .spp-hud-bar { flex-direction: column; align-items: flex-start; }
        .spp-hud-right { width: 100%; justify-content: space-between; }
        .spp-gal { height: 440px; }
        .spp-gal__node { width: 72px; height: 34px; font-size: 12px; }
        .spp-gal-wrap { --spp-gal-core: 104px; }
        .spp-modal-header { padding: 16px; }
        .spp-modal-body { padding: 16px; }
    }
    /* 2.57.59 补：站点开了「减少动态效果」时，本节的自转/呼吸一律停（旧版也有这条） */
    @media (prefers-reduced-motion: reduce) {
        .spp-accretion-disk, .spp-event-horizon, .spp-live-dot, .spp-gal__node.is-active {
            animation:none !important;
        }
    }
    /* 2.57.59 就地修正：核没有改成 <a>（见 JS 段头那条修正），原先给它补的两条链接兜底
       规则一并撤掉；核的链接是里面那枚「直达版区 ↗」，它本来就是 <a>，样式照参考稿。 */

    `;

        
        
        const CSS_TOPCARD = `
    .spp-top4 {
        /* ★ 2.52.96：卡片总高 = 内容盒 224 + 上下内边距 28 + 2px 描边 x2 = 256。
           站点是 box-sizing:content-box（实测 body/html 都是），所以高度必须由【槽位】给死；
           槽位与茶馆行共用同一个 --sz-card-h，两行三张卡才是同高（详解见 CSS_SUBCARD 顶注）。 */
        --sz-card-h:256px;
        display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px;
        margin:0 0 16px;
    }
    .spp-top4 > .spp-sc { height:var(--sz-card-h); }
    /* ★ 2.53.63（用户截图红框：「红色框选部分需要保持一定距离，太贴近了，看起来像是已经重叠」）：
       给宿主一个属于自己的上边距。站点在 #header 末尾放了一块 99px 高、mb:-5px 的广告位，
       广告拦截插件把它收掉之后 #main 就直接顶到信息区下沿 —— 线上实测：
       信息区 bottom = 277、卡片 top = 278，缝隙只有 1px，看着就是叠在一起；
       有广告时那道缝由广告位撑着（97px），所以这条只在装了拦截插件的机器上现形。
       加 16px 之后有没有广告都恒定有呼吸（16 = 本模块卡片间距，同 .spp-top4 的 gap）。
       ★ 为什么不用 #main{padding-top}：那会连版块页/帖子页的整页首块一起挪，本轮不碰。 */
    html.spp-hm-on .t.spp-top4-host { margin-top:16px !important; }
    .spp-top4 .spp-lt__hd { font-size:14px; color:#f0f5ff; letter-spacing:1.4px; }
    .spp-top4 .spp-lt__hd em { display:none; }
    .spp-top4 .spp-lt__hd a.spp-top4__hd {
        color:#f0f5ff !important; text-decoration:none !important;
        /* ★ 2.56.8：过渡里必须带上 text-shadow —— 否则颜色是渐变的、辉光是硬闪的，
           一眼看出两层不同步。 */
        transition:color .16s ease, text-shadow .16s ease;
        /* ★ 2.56.7：标题变成跳转链接后，点击面吃到整条标题行（.spp-lt__hd 是 flex 行），
           光标也给上手型 —— 否则只有一个行内小靶子，用户根本看不出这是能点的。 */
        flex:1 1 auto; min-width:0; cursor:pointer;
    }
    /* ★★ 2.56.8（用户任务 19 追加）：「鼠标经过的时候字体会变成荧光绿（科幻感的那种）」
       —— 荧光绿 #39ff14 + 双层辉光（贴着一层 6px、外扩一层 16px）：荧光绿本身在
       深色卡上就是「霓虹灯管」的色相，再叠两层同色辉光才有科幻那种发光感。
       ★ 只上这一条 hover（指向卡片自身的标题链接），不影响同排的蜜柑卡（它走变体结构）
         与下面两张「最新讨论 / 最新回复」卡（那两张的标题还是 <span>，压根配不到 a）。
       ★ 对比：荧光绿压在卡片底 #12161d 上 ≈ 13.2:1（WCAG AA 富余）。 */
    .spp-top4 .spp-lt__hd a.spp-top4__hd:hover {
        color:#39ff14 !important;
        text-shadow:0 0 6px rgba(57,255,20,.85), 0 0 16px rgba(57,255,20,.45);
    }
    .spp-top4 .spp-lt__list a { height:29px; font-size:13.5px; }

    /* ==================================================================
       蜜柑计划卡：Uiverse / ElSombrero2 / tricky-robin-67 —— 3D 翻转
       原版卡为 190x254 竖版；这里按版面改成与同排卡片一致的横版（由 .spp-top4 定高）。
       默认显示「背面」（.spp-mk__back：黑白小电视 + 旋转橙带），hover 翻出错面（信息面）。
       ================================================================== */
    .spp-sc--mikan { perspective:900px; }
    .spp-mk {
        position:absolute; inset:0;
        transform-style:preserve-3d;
        transition:transform 300ms;
        box-shadow:0 0 10px 1px #000000ee;
        border-radius:20px;
    }
    .spp-sc--mikan:hover .spp-mk { transform:rotateY(180deg); }
    .spp-mk__back, .spp-mk__front {
        position:absolute; inset:0; overflow:hidden; border-radius:20px;
        background-color:#151515;
        backface-visibility:hidden; -webkit-backface-visibility:hidden;
    }
    /* ---- 第一面（默认可见）：旋转的橙色光带 + 黑白小电视 ---- */
    .spp-mk__back { display:grid; place-items:center; }
    .spp-mk__back::before {
        position:absolute; content:''; display:block;
        width:46%; height:300%;
        background:linear-gradient(90deg,transparent,#ff9966,#ff9966,#ff9966,#ff9966,transparent);
        animation:sppMkSpin 5000ms infinite linear;
    }
    @keyframes sppMkSpin {
        0%   { transform:rotateZ(0deg); }
        100% { transform:rotateZ(360deg); }
    }
    .spp-mk__core {
        position:absolute; inset:1px; z-index:1; border-radius:19px;
        background-color:#151515;
        display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
        color:#fff;
    }
    .spp-mk__core strong {
        font-size:15px; font-weight:700; letter-spacing:3px; color:#f4f4f4;
        text-shadow:0 1px 3px rgba(0,0,0,.75);
    }
    /* ---- 第二面（翻转后）：信息面 ---- */
    .spp-mk__front { transform:rotateY(180deg); color:#fff; }
    .spp-mk__orbs { position:absolute; inset:0; z-index:1; pointer-events:none; }
    .spp-mk__orbs span {
        position:absolute; border-radius:50%; filter:blur(15px);
        animation:sppMkFloat 2600ms infinite linear;
    }
    .spp-mk__orbs .c1 { width:120px; height:120px; background:#ffbb66; left:10%;  top:46%; }
    .spp-mk__orbs .c2 { width:44px;  height:44px;  background:#ff2233; right:13%; top:8%;  animation-delay:-1800ms; }
    .spp-mk__orbs .c3 { width:150px; height:150px; background:#ff8866; left:32%;  top:88%; animation-delay:-800ms; }
    @keyframes sppMkFloat {
        0%   { transform:translateY(0); }
        50%  { transform:translateY(10px); }
        100% { transform:translateY(0); }
    }
    .spp-mk__frontcore {
        position:relative; z-index:2; height:100%; padding:14px 16px;
        box-sizing:border-box; overflow:hidden;
        display:flex; flex-direction:column; justify-content:space-between; gap:10px;
    }
    .spp-mk__badge {
        align-self:flex-start; flex:0 0 auto;
        background-color:rgba(0,0,0,.34); backdrop-filter:blur(2px);
        padding:3px 11px; border-radius:10px;
        font-size:11px; letter-spacing:1.6px; color:#ffd9c2;
        max-width:100%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
    }
    .spp-mk__desc {
        flex:0 1 auto; min-height:0;
        background-color:rgba(0,0,0,.62); backdrop-filter:blur(5px);
        border-radius:10px; padding:10px 13px;
        box-shadow:0 0 10px 5px rgba(0,0,0,.53);
    }
    .spp-mk__title {
        display:flex; align-items:center; justify-content:space-between; gap:10px;
        font-size:13px; font-weight:700; color:#fff; line-height:1.3;
    }
    .spp-mk__title span { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
    .spp-mk__title svg { flex:0 0 auto; fill:#20c997; }
    .spp-mk__foot {
        margin:5px 0 0; font-size:11px; line-height:1.45;
        color:rgba(255,255,255,.66);
        /* 最多两行，超出省略 —— 简介可能很长，绝不能撑破卡片 */
        display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical;
        overflow:hidden;
    }
    /* 外链提示行（蜜柑计划指向站外站点） */
    .spp-mk__foot--host {
        display:block; margin-top:3px; -webkit-line-clamp:none;
        color:rgba(255,153,102,.82); letter-spacing:.4px;
    }
    /* 整卡热区：盖住两面，点哪都能进板块 */
    .spp-mk__link { position:absolute; inset:0; z-index:300; display:block; }

    /* ---- 黑白小电视图标：默认 19px；蜜柑卡第一面放大到 64px ---- */
    .spp-bili {
        flex:0 0 auto; width:19px; height:19px;
        fill:none; stroke:currentColor; stroke-width:1.7;
        stroke-linecap:round; stroke-linejoin:round;
        color:#f4f4f4; vertical-align:middle;
        filter:drop-shadow(0 0 5px rgba(255,255,255,.22));
        transition:color .16s ease, filter .16s ease;
    }
    .spp-mk__core .spp-bili {
        width:64px; height:64px; stroke-width:1.5;
        filter:drop-shadow(0 0 9px rgba(255,255,255,.28));
    }
    .spp-sc--mikan:hover .spp-bili { color:#fff; filter:drop-shadow(0 0 8px rgba(255,255,255,.5)); }
    `;

        
        
