        function pickNewerCmSubs(all, archive) {
            const subs0 = (archive && archive.subs) || [];
            const have = {};
            const nums = subs0.map(function (s) {
                have[s.name] = 1;
                return parseInt(String(s.name).replace(/\D/g, ''), 10) || 0;
            });
            const top = nums.length ? Math.max.apply(null, nums) : 0;
            return (all || []).filter(function (r) {
                return r && typeof r.no === 'number' && r.no > top && !have['C' + r.no];
            }).sort(function (a, b) { return b.no - a.no; }).map(function (r) {
                const list = (r.subs || []).filter(function (s) { return !/图墙/.test(s.name); })[0];
                return {
                    name: 'C' + r.no,
                    href: (list && list.href) || r.href,
                    board: r.name,
                    boardHref: r.href
                };
            });
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        const GAL_ARCH_SUB = true;
        const GAL_ARCH_SUB_KEY = 'spp261:archsub';
        const GAL_ARCH_SUB_TTL = 72 * 60 * 60 * 1000;

        function galArchSubCache() {
            try {
                const raw = window.localStorage.getItem(GAL_ARCH_SUB_KEY);
                const o = raw ? JSON.parse(raw) : null;
                if (o && o.m && o.t && (Date.now() - o.t) < GAL_ARCH_SUB_TTL) return o;
            } catch (e) {  }
            return { m: {}, t: Date.now() };
        }

        
        
        
        
        
        
        
        function parseArchSubHref(html, base) {
            if (!html || html.indexOf('cate_children') < 0) return null;
            const doc = new DOMParser().parseFromString(html, 'text/html');
            const tb = doc.getElementById('cate_children');
            if (!tb) return null;
            const links = [].slice.call(tb.querySelectorAll('h2 a'));
            let fallback = null;
            for (let i = 0; i < links.length; i++) {
                const t = (links[i].textContent || '').trim();
                if (!t || /图墙/.test(t)) continue;
                const raw = links[i].getAttribute('href');
                const url = raw ? (function () {
                    try { return new URL(raw, base).href; } catch (e) { return raw; }
                })() : (links[i].href || null);
                if (/同人志/.test(t)) return url;          
                if (!fallback) fallback = url;
            }
            return fallback;
        }

        
        function applyArchSub(sub, anchor, href) {
            if (!sub || !href || sub.href === href) return;
            sub.href = href;
            sub.subHref = href;
            if (anchor) anchor.setAttribute('href', href);
        }

        
        function galArchSubRefresh() {
            const subs = (GAL_INFO && GAL_INFO.subs) || [];
            if (GAL_SELECT && GAL_TARGET >= 0 && subs[GAL_TARGET]) GAL_SELECT(GAL_TARGET);
            if (GAL_MODAL && GAL_MODAL.backdrop.classList.contains('open') && subs[GAL_MODAL_INDEX]) {
                GAL_MODAL.jump.href = subs[GAL_MODAL_INDEX].href;
            }
        }

        function resolveArchSubs(stage, nodes, subsAll) {
            if (!GAL_ARCH_SUB || !window.fetch || !subsAll || !subsAll.length) return;
            const cache = galArchSubCache();
            const todo = [];
            let changed = false;
            subsAll.forEach(function (s, idx) {
                if (!s || !s.fromBoard || !s.boardHref) return;   
                const hit = cache.m[s.boardHref];
                if (hit === 0) return;                            
                if (hit) { applyArchSub(s, nodes[idx], hit); changed = true; return; }
                todo.push({ sub: s, anchor: nodes[idx] });
            });
            if (changed) galArchSubRefresh();
            if (!todo.length) return;

            let cursor = 0, live = 0;
            function save() {
                try { window.localStorage.setItem(GAL_ARCH_SUB_KEY, JSON.stringify(cache)); } catch (e) {}
            }
            function tick() {
                while (live < 2 && cursor < todo.length) {
                    const job = todo[cursor++];
                    let base = job.sub.boardHref;
                    try { base = new URL(base, location.href).href; } catch (e) {}
                    live++;
                    window.fetch(base, { credentials: 'same-origin', cache: 'no-store' })
                        .then(function (r) { return r.ok ? r.text() : ''; })
                        .then(function (html) {
                            const href = parseArchSubHref(html, base);
                            cache.m[job.sub.boardHref] = href || 0;
                            if (href) { applyArchSub(job.sub, job.anchor, href); galArchSubRefresh(); }
                            save();
                        })
                        
                        .catch(function () {})
                        .then(function () { live--; window.setTimeout(tick, 400); });
                }
            }
            window.setTimeout(tick, 0);
        }

        
        
        
