        function renderSubCards() {
            if (!onSub) return;
            const cw = document.querySelector('#content > .contentwrap');
            if (!cw || cw.querySelector('.spp-sz')) return;
            const cate = document.getElementById('cate_7');
            if (!cate) return;
            const all = [].slice.call(cate.querySelectorAll('tr.f_one[id^="fid_"]'))
                .map(parseBoardRow).filter(Boolean);
            if (!all.length) return;

            const zone = document.createElement('div');
            zone.className = 'spp-sz';

            
            const picked = SZ_GROUPS.map(function (name) {
                return all.filter(function (r) { return r.name === name; })[0];
            }).filter(Boolean);
            if (!picked.length) return;

            picked.forEach(function (info) {
                const g = document.createElement('div');
                const isTea = info.name === SZ_TEA;
                g.className = 'spp-sz-group' + (isTea ? ' is-center'
                    : (info.name === '网赚资源区' ? ' is-net' : ' is-sec'));

                const hd = document.createElement('div');
                hd.className = 'spp-sz-hd spp-uvbtn';
                hd.innerHTML =
                    '<a class="spp-sz-hd__t" href="' + info.href + '" target="_blank" rel="noopener">' + esc(info.name) + '</a>' +
                    '<span class="spp-sz-hd__meta">' + comma(info.topics) + ' 主题<i>·</i>' + comma(info.posts) + ' 帖' +
                        (typeof info.today === 'number' ? '<i>·</i>今日 <b>' + (info.today > 0 ? '+' + info.today : '0') + '</b>' : '') +
                    '</span>' +
                    '<span class="spp-sz-hd__cnt">' + info.subs.length + ' 子版</span>';
                g.appendChild(hd);

                const grid = document.createElement('div');
                grid.className = 'spp-sz-grid';

                if (isTea) {
                    
                    
                    const snap = collectTopCols();
                    const pick = function (name) {
                        return snap ? snap.cols.filter(function (c) { return c.title === name; })[0] : null;
                    };
                    const l = pick('最新讨论'), r = pick('最新回复');
                    if (l) grid.appendChild(buildTopCard(l.title, l.links, l.href || null));
                    grid.appendChild(buildTeaCard(info));
                    if (r) grid.appendChild(buildTopCard(r.title, r.links, r.href || null));
                } else {
                    
                    const tagPre = (info.name === '网赚资源区') ? 'NET' : 'SEC';
                    info.subs.forEach(function (sub, si) {
                        grid.appendChild(buildSubCard(sub, tagPre + '-' + (si < 9 ? '0' : '') + (si + 1)));
                    });
                }
                g.appendChild(grid);
                zone.appendChild(g);
            });

            if (!zone.children.length) return;
            cw.insertBefore(zone, cw.firstChild);
        }

        
        
        let TOP_SNAPSHOT = null;

        
        
        function collectTopCols() {
            if (TOP_SNAPSHOT) return TOP_SNAPSHOT;
            const wrap = document.querySelector('#main > div.t');
            if (!wrap) return null;
            const tbl = wrap.querySelector('table');
            if (!tbl || tbl.rows.length < 2) return null;
            const headRow = tbl.rows[0], bodyRow = tbl.rows[1];
            if (headRow.cells.length !== 4 || bodyRow.cells.length !== 4) return null;
            const cols = [];
            for (let i = 0; i < 4; i++) {
                const title = headRow.cells[i].textContent.replace(/\s+/g, ' ').trim();
                const links = [].slice.call(bodyRow.cells[i].querySelectorAll('a'))
                    .filter(function (a) { return (a.textContent || '').trim(); });
                if (!title || !links.length) return null;   
                cols.push({ title: title, links: links });
            }
            TOP_SNAPSHOT = { wrap: wrap, tbl: tbl, cols: cols };
            return TOP_SNAPSHOT;
        }

        
        
        
