        function buildBoardGrid(targets, badgeEm, badgeMap, keepList) {
            const grid = document.createElement('div');
            
            
            grid.className = 'spp-cm-grid' + (targets.length === 1 ? ' is-single' : '');
            targets.forEach(function (t) {
                
                
                
                const keys = keepList || [];
                const key = keys.filter(function (k) {
                    return t.name === k || String(t.name).indexOf(k) === 0;
                })[0] || t.name;
                const info = Object.assign({}, t, {
                    badgeEm: badgeEm,
                    badgeNo: (badgeMap && badgeMap[key]) || String(t.name).trim().slice(0, 2)
                });
                grid.appendChild(buildCmCard(info));
            });
            return grid;
        }

        
