    function initTaskAutoClaim() {
        
        
        
        
        if (!SPP_CONFIG.bool('spp_task_autoclaim', true)) return;

        GM_addStyle(
            '#spp-task-toast {' +
            'position:fixed; right:18px; bottom:18px; z-index:100004;' +
            'max-width:min(370px, calc(100vw - 36px)); padding:12px 15px; border-radius:12px;' +
            'background-color:rgba(10,14,22,0.94);' +
            'background-image:linear-gradient(180deg, rgba(255,255,255,0.07) 0%, rgba(255,255,255,0) 70%);' +
            'background-repeat:no-repeat; color:#dbe4ef; border:1px solid rgba(255,255,255,0.10);' +
            'box-shadow:0 20px 54px rgba(2,6,23,0.6), inset 0 1px 0 rgba(255,255,255,0.06);' +
            'backdrop-filter:blur(14px) saturate(140%); -webkit-backdrop-filter:blur(14px) saturate(140%);' +
            'font-size:12.5px; line-height:1.75; opacity:0; transform:translateY(10px);' +
            'pointer-events:none; transition:opacity .3s ease, transform .3s ease; }' +
            '#spp-task-toast.spp-on { opacity:1; transform:translateY(0); }' +
            '#spp-task-toast .spp-tt-h { color:#eaf2fb; font-weight:650; margin-bottom:3px; }' +
            '#spp-task-toast .spp-tt-b { color:#9fb0c4; }'
        );

        const LAST = 'spp_task_claim_at';
        const LOG = 'spp_task_claimed';
        const GAP = 3 * 60 * 60 * 1000;   
        
        
        
        
        const GUARD = 24 * 60 * 60 * 1000;
        const TASK_URL = 'plugin.php?H_name-tasks.html';
        const RUN_URL = 'plugin.php?H_name-tasks-actions-newtasks.html.html';
        
        
        const JOB = 'plugin.php?H_name=tasks&action=ajax&actions=job&cid=';
        const JOB2 = 'plugin.php?H_name=tasks&action=ajax&actions=job2&cid=';
        const ON_TASK = isTaskPage();
        const now = Date.now();
        if (!ON_TASK && now - (Number(GM_getValue(LAST, 0)) || 0) < GAP) return;
        GM_setValue(LAST, now);

        
        function cidsFrom(html) {
            const out = [];
            let m;
            const reJob = /startjob\(\s*(\d+)\s*\)/g;
            while ((m = reJob.exec(html))) if (out.indexOf(m[1]) < 0) out.push(m[1]);
            if (!out.length && html.indexOf('startjob') >= 0) {
                const reId = /\bid=["']p_(\d+)["']/g;
                while ((m = reId.exec(html))) if (out.indexOf(m[1]) < 0) out.push(m[1]);
            }
            return out;
        }
        function scanDoc() {
            return Promise.resolve(cidsFrom(document.documentElement.innerHTML));
        }
        function scanUrl(url) {
            const u = url + (url.indexOf('?') < 0 ? '?' : '&') + '_spp=' + Date.now();
            return fetch(u, { credentials: 'same-origin' })
                .then(function (r) { return r.ok ? r.text() : ''; })
                .then(cidsFrom)
                .catch(function () { return []; });
        }
        
        
        function scanAll() {
            const jobs = [scanUrl(TASK_URL), scanUrl(RUN_URL)];
            if (ON_TASK) jobs.push(scanDoc());
            return Promise.all(jobs).then(function (rs) {
                const list = [];
                rs.forEach(function (a) {
                    (a || []).forEach(function (c) { if (list.indexOf(c) < 0) list.push(c); });
                });
                return list;
            });
        }
        
        function post(url) {
            return fetch(url + '&nowtime=' + Date.now(),
                { credentials: 'same-origin', headers: { 'X-Requested-With': 'XMLHttpRequest' } })
                .then(function (r) { return r.text(); })
                .then(function (txt) {
                    const cd = /<!\[CDATA\[([\s\S]*?)\]\]>/.exec(txt);
                    const parts = (cd ? cd[1] : txt).split('\t');
                    return { ok: parts[0] === 'success', msg: (parts[1] || '').trim(), tid: (parts[2] || '').trim() };
                })
                .catch(function () { return { ok: false, msg: '请求失败' }; });
        }
        
        
        
        
        function claim(cid) {
            return post(JOB + cid).then(function (ap) {
                const h = /还没超过\s*(\d+)\s*小时/.exec(ap.msg || '');
                return post(JOB2 + cid).then(function (g) {
                    g.cid = cid;
                    g.step = ap.msg;
                    g.wait = h ? Number(h[1]) * 3600 * 1000 : 0;
                    return g;
                });
            });
        }
        
        function gateRead() {
            try { return JSON.parse(GM_getValue(LOG, '{}')) || {}; } catch (_) { return {}; }
        }
        function gateLeft(g, cid) {
            const r = g[cid];
            if (!r) return 0;
            const until = Math.max((Number(r.at) || 0) + GUARD, Number(r.until) || 0);
            return until - Date.now();
        }
        function gateSave(g) {
            try { GM_setValue(LOG, JSON.stringify(g)); } catch (_) { }
        }
        function toast(title, lines) {
            if (!document.body) { onDomReady(function () { toast(title, lines); }); return; }
            let box = document.getElementById('spp-task-toast');
            if (!box) { box = document.createElement('div'); box.id = 'spp-task-toast'; document.body.appendChild(box); }
            box.textContent = '';
            const h = document.createElement('div');
            h.className = 'spp-tt-h';
            h.textContent = title;
            box.appendChild(h);
            lines.forEach(function (t) {
                const d = document.createElement('div');
                d.className = 'spp-tt-b';
                d.textContent = t;
                box.appendChild(d);
            });
            void box.offsetHeight;
            box.classList.add('spp-on');
            if (box.__sppT) clearTimeout(box.__sppT);
            box.__sppT = setTimeout(function () { box.classList.remove('spp-on'); }, 9000);
        }

        let running = false;
        function run() {
            if (running) return Promise.resolve({ skipped: 'already-running' });
            running = true;
            const gate = gateRead();
            const res = {};
            const got = [];
            const found = [];   
            let scanned = 0;
            
            
            
            function round(n) {
                return scanAll().then(function (cids) {
                    cids.forEach(function (c) { if (found.indexOf(c) < 0) found.push(c); });
                    const todo = cids.filter(function (c) {
                        if (gateLeft(gate, c) > 0) return false;
                        if (n === 0) return true;
                        const r = res[c];
                        return !!(r && r.round === 0 && !r.ok && !r.wait);
                    });
                    if (!todo.length) return;
                    scanned += todo.length;
                    return todo.reduce(function (p, c) {
                        return p.then(function () {
                            return claim(c).then(function (g) {
                                g.round = n;
                                res[c] = g;
                                got.push(g);
                                
                                
                                if (g.ok) { gate[c] = { at: Date.now() }; gateSave(gate); }
                                else if (g.wait) { gate[c] = { until: Date.now() + g.wait }; gateSave(gate); }
                            });
                        });
                    }, Promise.resolve()).then(function () {
                        if (n > 0) return;
                        return new Promise(function (x) { setTimeout(x, 1500); }).then(function () { return round(1); });
                    });
                });
            }
            return round(0).then(function () {
                running = false;
                gateSave(gate);
                const ok = got.filter(function (g) { return g.ok; });
                const no = got.filter(function (g) { return !g.ok; });
                const out = { found: found, scanned: scanned, ok: ok.length, rejected: no.length, results: got };
                if (ok.length) {
                    toast('社区论坛任务 · 自动领取 ' + ok.length + ' 项',
                        ok.map(function (g) { return '✓ ' + (g.msg || ('cid ' + g.cid)); }));
                    console.info('[SPP] 社区论坛任务自动领取成功：', out);
                } else {
                    console.info('[SPP] 社区论坛任务自动领取：本次没有可领取的任务（尝试 ' + scanned + ' 枚按钮）', out);
                }
                return out;
            }).catch(function (e) {
                running = false;
                console.warn('[SPP] 社区论坛任务自动领取异常：', e);
                return { error: String(e) };
            });
        }

        window.__SPP_TASKS = {
            run: run,
            scan: function () { return scanAll(); },
            urls: [TASK_URL, RUN_URL]
        };

        
        
        
        
        document.addEventListener('spp-tasks-run', function () { run(); });

        if (document.readyState === 'interactive' || document.readyState === 'complete') {
            setTimeout(function () { run(); }, 500);
        } else {
            onDomReady(function () { setTimeout(function () { run(); }, 500); });
        }
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const sppDrops = [];
    function sppDropsClose(except) {
        sppDrops.forEach(function (d) { if (d !== except) d.close(); });
    }
    document.addEventListener('click', function () { sppDropsClose(null); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') sppDropsClose(null); });

    function initDropdowns(root) {
        if (!root) return 0;
        let n = 0;
        Array.prototype.forEach.call(root.querySelectorAll('select'), function (sel) {
            if (sel.dataset.sppDd) return;
            sel.dataset.sppDd = '1';
            n++;

            const wrap = document.createElement('span');
            wrap.className = 'spp-dd';
            sel.parentNode.insertBefore(wrap, sel);
            wrap.appendChild(sel);

            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'spp-dd-btn';
            btn.setAttribute('aria-haspopup', 'listbox');
            btn.setAttribute('aria-expanded', 'false');
            const txt = document.createElement('span');
            txt.className = 'spp-dd-txt';
            const car = document.createElement('span');
            car.className = 'spp-dd-caret';
            car.setAttribute('aria-hidden', 'true');
            btn.appendChild(txt);
            btn.appendChild(car);

            const pop = document.createElement('div');
            pop.className = 'spp-dd-pop';
            pop.setAttribute('role', 'listbox');
            const opts = [];
            Array.prototype.forEach.call(sel.options, function (o, i) {
                const d = document.createElement('div');
                d.className = 'spp-dd-opt';
                d.setAttribute('role', 'option');
                d.dataset.i = String(i);
                
                d.textContent = String(o.text).replace(/\s+/g, ' ').trim();
                pop.appendChild(d);
                opts.push(d);
            });
            wrap.appendChild(btn);
            wrap.appendChild(pop);

            let hi = 0;
            function paint() {
                opts.forEach(function (d, i) {
                    d.classList.toggle('is-on', i === sel.selectedIndex);
                    d.classList.toggle('is-hi', i === hi);
                });
            }
            function reveal() {
                const on = opts[hi];
                if (on && on.scrollIntoView) on.scrollIntoView({ block: 'nearest' });
            }
            function sync() {
                txt.textContent = opts[sel.selectedIndex] ? opts[sel.selectedIndex].textContent : '';
                paint();
            }
            const api = {
                isOpen: function () { return wrap.classList.contains('is-open'); },
                close: function () {
                    wrap.classList.remove('is-open');
                    btn.setAttribute('aria-expanded', 'false');
                },
                open: function () {
                    sppDropsClose(api);
                    wrap.classList.add('is-open');
                    btn.setAttribute('aria-expanded', 'true');
                    hi = Math.max(0, sel.selectedIndex);
                    paint();
                    reveal();
                },
                move: function (dy) {
                    hi = Math.min(opts.length - 1, Math.max(0, hi + dy));
                    paint();
                    reveal();
                },
                take: function () {
                    sel.selectedIndex = hi;
                    sel.dispatchEvent(new Event('change', { bubbles: true }));
                    sync();
                    api.close();
                    btn.focus();
                }
            };
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                if (api.isOpen()) api.close(); else api.open();
            });
            btn.addEventListener('keydown', function (e) {
                if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (api.isOpen()) api.move(e.key === 'ArrowDown' ? 1 : -1); else api.open();
                } else if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    if (api.isOpen()) api.take(); else api.open();
                } else if (e.key === 'Escape') {
                    api.close();
                }
            });
            opts.forEach(function (d, i) {
                d.addEventListener('mouseenter', function () { hi = i; paint(); });
                d.addEventListener('click', function (e) { e.stopPropagation(); hi = i; api.take(); });
            });
            sppDrops.push(api);
            sync();
        });
        return n;
    }
    
    
    
    
    
    
    
    
    function sppSyncDayFromUrl(root) {
        const m = location.href.match(/search-([a-z0-9]+?)-page-/) ||
            location.href.match(/[?&]search=([a-z0-9]+)/);
        if (!m) return '';
        const sel = root.querySelector('select[name="search"]');
        if (!sel) return '';
        const hit = Array.prototype.filter.call(sel.options, function (o) { return o.value === m[1]; })[0];
        if (!hit) return '';
        sel.selectedIndex = hit.index;
        return m[1];
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    function sppFilterUrl() {
        const fm = location.href.match(/fid-(\d+)/) || location.href.match(/[?&]fid=(\d+)/);
        if (!fm) return '';
        const form = document.querySelector('#main .spp-t5bar form');
        if (!form) return '';
        const val = function (name) { const e = form.elements[name]; return e ? String(e.value || '') : ''; };
        const day = val('search');          
        const way = val('orderway') || 'lastpost';
        const dir = val('asc') === 'ASC' ? 'ASC' : 'DESC';
        const pm = location.href.match(/page-(\d+)/) || location.href.match(/[?&]page=(\d+)/);
        const page = (pm && pm[1]) || '1';
        
        const seg = function (k) {
            const m = location.href.match(new RegExp(k + '-(\\d+)')) ||
                location.href.match(new RegExp('[?&]' + k + '=(\\d+)'));
            return m ? m[1] : '';
        };
        const type = seg('type'), special = seg('special');
        return location.origin + '/thread_new.php?fid-' + fm[1] +
            (type ? '-type-' + type : '') + (special ? '-special-' + special : '') +
            (day ? '-search-' + day : '') +
            (way === 'lastpost' && dir === 'DESC' ? '' : '-orderway-' + way + '-asc-' + dir) +
            '-page-' + page + '.html';
    }

    function initT5Apply(root) {
        const btn = root.querySelector('form input.btn');
        if (!btn || btn.dataset.sppApply) return 0;         
        btn.dataset.sppApply = '1';
        
        
        
        document.addEventListener('click', function (ev) {
            if (ev.target !== btn) return;
            const url = sppFilterUrl();
            if (!url) return;                               
            ev.preventDefault();
            ev.stopPropagation();
            sppDropsClose(null);                            
            location.href = url;
        }, true);
        return 1;
    }
    

    function initBoardNotice() {
        if (!PAGE.board) return;
        onDomReady(function () {
            if (document.getElementById('spp-btabs')) return;      

            const cat = document.getElementById('cate_thread');
            const panel = document.getElementById('spp-announce');   

            
            let rules = null, cover = null, pan = null;
            if (cat) {
                pan = Array.from(cat.children).find(function (c) {
                    return c.classList && c.classList.contains('tr1') &&
                        (c.textContent || '').replace(/\s+/g, '').length >= 40;
                });
                if (pan) {
                    const nodes = [];
                    
                    
                    
                    Array.from(pan.childNodes).forEach(function (n) {
                        if (n.nodeType === 1) {
                            
                            if (!cover && n.tagName === 'DIV' && n.hasAttribute('align') && n.querySelector('img')) {
                                cover = n;
                                return;
                            }
                            nodes.push(n);
                        } else if (n.nodeType === 3 && n.textContent.trim()) {
                            nodes.push(n);
                        }
                    });
                    if (nodes.length) rules = nodes;
                }
            }
            let subs = null;
            const subBody = document.getElementById('cate_children');
            if (subBody) {
                const tb = subBody.closest('table');
                subs = (tb && tb.parentElement) || tb;
            }
            
            
            
            let cats = null, catsWrap = null;
            const catRow = document.querySelector('#ajaxtable ul.threadlist') || document.querySelector('ul.threadlist');
            if (catRow && Array.prototype.some.call(catRow.querySelectorAll('li[id^="thread_type_"]'), function (li) {
                return li.id !== 'thread_type_all' && li.id !== 'thread_type_digest';
            })) {
                cats = catRow;
                catsWrap = catRow.closest('.hthread') || catRow.parentElement;   
            }

            
            if (!panel) {
                if (!rules || document.getElementById('spp-bnotice')) return;
                const anchor = document.createComment('spp-bnotice');
                rules[0].parentNode.insertBefore(anchor, rules[0]);

                const box = document.createElement('section');
                box.id = 'spp-bnotice';
                box.dataset.open = '0';                 
                const head = document.createElement('button');
                head.type = 'button';
                head.className = 'spp-ann-head';
                head.setAttribute('aria-expanded', 'false');
                const t = document.createElement('span');
                t.className = 'spp-ann-title';
                t.textContent = '本版公告';
                const h = document.createElement('span');
                h.className = 'spp-ann-hint';
                h.textContent = '版规与注意事项';
                const cv = document.createElement('span');
                cv.className = 'spp-ann-chev';
                cv.setAttribute('aria-hidden', 'true');
                head.appendChild(t); head.appendChild(h); head.appendChild(cv);
                const body = document.createElement('div');
                body.className = 'spp-ann-body';
                const inner = document.createElement('div');
                inner.className = 'spp-ann-inner';
                const raw = document.createElement('div');
                raw.className = 'spp-ann-raw';
                rules.forEach(function (n) { raw.appendChild(n); });
                inner.appendChild(raw);
                body.appendChild(inner);
                box.appendChild(head);
                box.appendChild(body);
                anchor.parentNode.replaceChild(box, anchor);
                head.addEventListener('click', function () {
                    const open = box.dataset.open === '1';
                    box.dataset.open = open ? '0' : '1';
                    head.setAttribute('aria-expanded', open ? 'false' : 'true');
                });
                return;
            }

            
            const panes = {};
            Array.prototype.forEach.call(panel.querySelectorAll('.spp-pane'), function (p) {
                panes[p.dataset.pane] = p;
            });

            function put(key, wrapCls, nodes) {
                const pane = panes[key];
                if (!pane) return false;
                const wrap = document.createElement('div');
                wrap.className = wrapCls;
                nodes.forEach(function (n) { wrap.appendChild(n); });
                pane.appendChild(wrap);
                return true;
            }

            const countEl = panel.querySelector('.spp-ann-count');
            const tabs = [];
            
            const noticeNum = countEl ? String(countEl.textContent).trim() : '';
            if (panes.notice && noticeNum !== '0') {
                tabs.push({ key: 'notice', name: '公告', hint: '置顶与论坛公告', num: noticeNum });
            }
            if (rules && put('rules', 'spp-ann-raw', rules)) {
                tabs.push({ key: 'rules', name: '本版公告', hint: '版规与注意事项' });
            }
            if (subs && put('subs', 'spp-pane-subs', [subs])) {
                tabs.push({ key: 'subs', name: '子版块', hint: '本版子版块' });
            }
            if (cover && put('cover', 'spp-pane-cover', [cover])) {
                tabs.push({ key: 'cover', name: '版头图', hint: '本板块图片' });
            }
            
            if (cats && put('cats', 'spp-pane-cats', [cats])) {
                tabs.push({
                    key: 'cats', name: '分类',
                    hint: Array.prototype.map.call(cats.querySelectorAll('li'), function (li) {
                        return (li.textContent || '').replace(/\s+/g, '');
                    }).filter(Boolean).join(' / ')
                });
                if (catsWrap && !catsWrap.children.length) {
                    catsWrap.style.setProperty('display', 'none', 'important');
                }
            }
            if (tabs.length < 2) return;                 

            
            const bar = document.createElement('section');
            bar.id = 'spp-btabs';
            bar.className = 'spp-paired';
            const btns = tabs.map(function (it, i) {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'spp-tab' + (i === 0 ? ' is-on' : '');
                b.dataset.pane = it.key;
                b.dataset.name = it.name;
                b.dataset.hint = it.hint || '';
                b.dataset.num = it.num || '';
                b.appendChild(document.createTextNode(it.name));
                if (it.num) {
                    const n = document.createElement('span');
                    n.className = 'spp-tab-n';
                    n.textContent = String(it.num);
                    b.appendChild(n);
                }
                return b;
            });
            btns.forEach(function (b, i) {
                if (i) {
                    const d = document.createElement('span');
                    d.className = 'spp-tab-div';
                    d.setAttribute('aria-hidden', 'true');
                    bar.appendChild(d);
                }
                bar.appendChild(b);
            });

            
            const titleEl = panel.querySelector('.spp-ann-title');
            const hintEl = panel.querySelector('.spp-ann-hint');
            function activate(btn, open) {
                btns.forEach(function (b) { b.classList.toggle('is-on', b === btn); });
                Array.prototype.forEach.call(panel.querySelectorAll('.spp-pane'), function (p) {
                    p.classList.toggle('is-on', p.dataset.pane === btn.dataset.pane);
                });
                if (titleEl) titleEl.textContent = btn.dataset.name;
                if (countEl) {
                    countEl.textContent = btn.dataset.num || '';
                    countEl.style.display = btn.dataset.num ? '' : 'none';
                }
                if (hintEl) hintEl.textContent = btn.dataset.hint || '';
                if (open) panel.dataset.open = '1';
            }
            btns.forEach(function (b) {
                b.addEventListener('click', function () { activate(b, true); });
            });

            
            panel.classList.add('spp-paired');
            panel.parentElement.insertBefore(bar, panel);

            
            
            
            
            
            
            
            
            
            
            
            
            
            const defPane = SPP_PANE_DEFAULT[sppFidNum()] || '';
            const defBtn = defPane ? btns.filter(function (b) { return b.dataset.pane === defPane; })[0] : null;
            activate(defBtn || btns[0], !!defBtn);
            if (defBtn) {
                const headBtn = panel.querySelector('.spp-ann-head');
                if (headBtn) headBtn.setAttribute('aria-expanded', 'true');
            }


            
            
            
            
            
            
            
            
            
            
            
            sppAskChipMount(bar, cats);   
            if (!cats && catRow) {
                const catBox = document.createElement('div');
                catBox.className = 'spp-catrow';
                catBox.appendChild(catRow);
                bar.appendChild(catBox);
                sppTeaChipMount(catBox);      

                
                
                
                const holder = catRow.parentElement;
                const rowEl = (holder && holder.closest('tr')) || holder;
                if (rowEl && !rowEl.querySelector('a, img, input, table, button') &&
                    !(rowEl.textContent || '').replace(/\s+/g, '').length) {
                    rowEl.style.setProperty('display', 'none', 'important');
                }
            }

            
            
            
            
            
            const t5bar = Array.prototype.filter.call(
                document.querySelectorAll('#main > div.t5'),
                function (el) {
                    return !el.classList.contains('t_one') && !!el.querySelector('table.f_one');
                }
            )[0];
            if (t5bar && !t5bar.classList.contains('spp-t5bar')) {
                t5bar.classList.add('spp-t5bar');
                bar.parentNode.insertBefore(t5bar, bar);
                sppSyncDayFromUrl(t5bar);
                initDropdowns(t5bar);
                initT5Apply(t5bar);
            }


            
            
            
            const panels = cat ? Array.from(cat.querySelectorAll('.tr1')) : [];
            const emptied = !!pan && panels.length > 0 && panels.every(function (p) {
                return p.children.length === 0 && !p.textContent.replace(/\s+/g, '').length;
            });
            if (emptied) {
                cat.style.setProperty('display', 'none', 'important');
                const gg = cat.closest('.gonggao');
                const legend = gg ? gg.querySelector('ul.gongul') : null;
                if (legend) legend.style.setProperty('display', 'none', 'important');
            }
        });
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
