    const SPP_SUB_ICON_BY_NAME = {
        'CG资源': 'palette',
        '同人音声': 'headphones',
        '实用动画': 'video',
        '高清里番': 'film',
        '实用漫画': 'book',
        '图墙模式': 'grid',
        '游戏资源': 'gamepad',
        'COSPLAY': 'camera',
        'GALGAME汉化区': 'heart',
        'GALGAME汉化区(图墙模式)': 'sparkles'
    };
    
    
    function sppSubIconKey(name) {
        const key = String(name || '').replace(/\s+/g, '').replace(/（/g, '(').replace(/）/g, ')');
        if (SPP_SUB_ICON_BY_NAME[key]) return SPP_SUB_ICON_BY_NAME[key];
        if (/图墙|瀑布|缩略图/.test(key)) return 'grid';
        if (/音声|音乐|ASMR|语音/.test(key)) return 'headphones';
        if (/动画|视频|里番|短片|映像|动图/.test(key)) return 'film';
        if (/漫画|图集|画册|画集|美术|图库|CG/i.test(key)) return 'book';
        if (/COS|写真|摄影|自拍/i.test(key)) return 'camera';
        if (/汉化|GAL/i.test(key)) return 'heart';
        if (/游戏|game/i.test(key)) return 'gamepad';
        if (/资源|专区|仓库|存档/.test(key)) return 'palette';
        return 'sparkles';
    }
    
    
    
    const SPP_SUB_BUBBLE = '<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"></path></svg>';
    function sppSubLastIcon(tr) {
        const cell = tr.querySelector('th.smalltxt');
        if (!cell || cell.dataset.sppBubble) return '';
        if (!cell.querySelector('a')) return '';        
        const ico = document.createElement('span');
        ico.className = 'spp-sub-last-ico';
        ico.setAttribute('aria-hidden', 'true');
        ico.innerHTML = SPP_SUB_BUBBLE;
        cell.dataset.sppBubble = '1';
        cell.insertBefore(ico, cell.firstChild);
        return 'bubble';
    }
    
    
    function sppSubTile(tr) {
        const tile = tr.children[0];
        if (!tile || tile.dataset.sppIcon) return '';
        const th = tr.querySelector('th[align="left"]');
        const nameA = th ? th.querySelector('h2 a') : null;
        const name = String((nameA ? nameA.textContent : '') || '').replace(/\s+/g, '');
        if (!name) return '';
        const key = sppSubIconKey(name);
        const ico = document.createElement('span');
        ico.className = 'spp-sub-ico';
        ico.setAttribute('aria-hidden', 'true');
        ico.innerHTML = SPP_SUB_ICONS[key] || SPP_SUB_ICONS.sparkles;
        tile.dataset.sppIcon = key;
        tile.appendChild(ico);
        return key;
    }

    function initSubsBento() {
        if (!PAGE.board) return 0;
        const cc = document.getElementById('cate_children');
        if (!cc) return 0;

        const rows = Array.prototype.filter.call(cc.children, function (tr) {
            return !!(tr.classList && tr.classList.contains('f_one'));
        });
        rows.forEach(function (tr) {
            if (tr.dataset.sppBento) return;
            tr.dataset.sppBento = '1';

            
            sppSubTile(tr);

            
            sppSubLastIcon(tr);

            
            const f10 = tr.querySelector('td.f10');
            if (f10) {
                const num = String(f10.textContent || '').replace(/[^0-9]/g, '');
                if (num && /^0+$/.test(num)) {
                    tr.dataset.sppWall = '1';
                    f10.dataset.sppPosts = '聚合检索';
                } else if (num) {
                    f10.dataset.sppPosts = num.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
                }
            }
        });
        return rows.length;
    }

    
    
    
    onDomReady(function () { initSubsBento(); });
    setTimeout(function () { initSubsBento(); }, 900);

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    

    
    const SPP_SUB_EPOCH = '1970-01-01';

    
    function sppSubAuthorOf(text) {
        const m = String(text || '').match(/楼主\s*[（(]([^）)\n]{1,40})[）)]/);
        return m ? String(m[1]).replace(/\s+/g, ' ').trim() : '';
    }
    
    
    function sppSubInitial(text) {
        const s = String(text || '').replace(/\s+/g, '');
        if (!s) return '';
        return Array.from(s)[0] || '';
    }

    
    
    
    
    
    function sppSubTray(tr) {
        const cell = tr.querySelector('th.smalltxt');
        if (!cell) return '';
        const h3 = cell.querySelector('h3');
        const link = h3 ? h3.querySelector('a') : null;
        if (!h3 || !link) { tr.dataset.sppNoreply = '1'; return 'noreply'; }

        const head = document.createElement('span');
        head.className = 'spp-sub-tray-head';

        
        const ico = cell.querySelector('.spp-sub-last-ico');
        if (ico) head.appendChild(ico);

        
        const author = sppSubAuthorOf(String(h3.textContent || ''));
        const ch = sppSubInitial(author) || sppSubInitial(String(link.textContent || ''));
        if (ch) {
            const avatar = document.createElement('span');
            avatar.className = 'spp-sub-avatar';
            avatar.setAttribute('aria-hidden', 'true');
            avatar.textContent = ch;
            head.appendChild(avatar);
        }

        
        if (author) {
            const who = document.createElement('span');
            who.className = 'spp-sub-author';
            who.textContent = author;
            head.appendChild(who);
        }

        
        const time = String(cell.getAttribute('title') || '').trim();
        if (time && time.indexOf(SPP_SUB_EPOCH) !== 0) {
            const t = document.createElement('span');
            t.className = 'spp-sub-time';
            t.textContent = time;
            head.appendChild(t);
        }

        
        const junk = document.createElement('span');
        junk.className = 'spp-sub-hash';
        junk.setAttribute('aria-hidden', 'true');
        let node = h3.nextSibling;
        while (node) {
            const next = node.nextSibling;
            junk.appendChild(node);
            node = next;
        }

        cell.insertBefore(head, cell.firstChild);
        cell.appendChild(junk);
        return 'tray';
    }

    
    function initSubsStar() {
        
        
        
        if (!sppSchemeStar()) return 0;
        if (!PAGE.board) return 0;
        const cc = document.getElementById('cate_children');
        if (!cc) return 0;

        const rows = Array.prototype.filter.call(cc.children, function (tr) {
            return !!(tr.classList && tr.classList.contains('f_one'));
        });
        if (!rows.length) return 0;

        
        let max = 0;
        const nums = rows.map(function (tr) {
            if (tr.dataset.sppWall) return 0;
            const f10 = tr.querySelector('td.f10');
            const n = f10 ? Number(String(f10.textContent || '').replace(/[^0-9]/g, '')) : 0;
            if (n > max) max = n;
            return n;
        });

        rows.forEach(function (tr, i) {
            if (tr.dataset.sppStar) return;
            tr.dataset.sppStar = '1';

            
            sppSubTray(tr);

            
            if (tr.dataset.sppWall) return;
            if (max > 0 && nums[i] > 0) {
                const pct = Math.round((nums[i] / max) * 100);
                tr.style.setProperty('--spp-heat', pct + '%');
                if (pct >= 75) tr.dataset.sppHot = '1';
            }
        });
        return rows.length;
    }

    
    
    onDomReady(function () { initSubsStar(); });
    setTimeout(function () { initSubsStar(); }, 950);

    
    
    
    
    
    
    
    
    
    
    
