    const SPP_SUB_GOLD_NAME = 'C100';

    function sppSubChip(cls, txt, tone) {
        const s = document.createElement('span');
        s.className = cls;
        if (tone) s.dataset.tone = tone;
        s.textContent = txt;
        return s;
    }

    
    
    function sppSubMeta(tr) {
        const th = tr.querySelector('th[align="left"]');
        if (!th || th.dataset.sppMeta) return '';
        const a = th.querySelector('h2 a');
        const name = String(a ? a.textContent : '').replace(/\s+/g, '');
        if (!name) return '';
        const row = SPP_SUB_COMIKET[name];
        if (!row) return '';
        const h2 = th.querySelector('h2');
        if (!h2) return '';

        th.dataset.sppMeta = '1';
        const winter = row[1] === 'winter';
        const nodes = [
            sppSubChip('spp-sub-year', '/ ' + row[0], ''),
            null,                                                     
            sppSubChip('spp-sub-season', winter ? '❄️ 冬Comi' : '☀️ 夏Comi', row[1])
        ];
        const brk = document.createElement('span');
        brk.className = 'spp-sub-brk';
        brk.setAttribute('aria-hidden', 'true');
        nodes[1] = brk;
        if (row[2]) nodes.splice(2, 0, sppSubChip('spp-sub-ms', row[2], name === SPP_SUB_GOLD_NAME ? 'gold' : 'rose'));
        if (name === SPP_SUB_GOLD_NAME) tr.dataset.sppGold = '1';

        let anchor = h2;
        nodes.forEach(function (n) { anchor.parentNode.insertBefore(n, anchor.nextSibling); anchor = n; });
        return name + ' ' + row[0] + ' ' + row[1] + (row[2] ? ' ' + row[2] : '');
    }

    function initSubsMeta() {
        
        
        
        if (!sppSchemeStar()) return 0;
        if (!PAGE.board) return 0;
        const cc = document.getElementById('cate_children');
        if (!cc) return 0;
        const rows = Array.prototype.filter.call(cc.children, function (tr) {
            return !!(tr.classList && tr.classList.contains('f_one'));
        });
        let n = 0;
        rows.forEach(function (tr) { if (sppSubMeta(tr)) n++; });
        return n;
    }

    onDomReady(function () { initSubsMeta(); });
    setTimeout(function () { initSubsMeta(); }, 1040);

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
