    function initProfileLayout() {
        onDomReady(function () {
            if (!document.getElementById('set-wrap')) return;   
            const CARDS = [
                '#set-content .set-content-left > div:first-child',   
                '#set-content .set-content-right > div:not(.c)'       
            ];
            CARDS.forEach(function (sel) {
                Array.prototype.forEach.call(document.querySelectorAll(sel), function (el) {
                    el.style.setProperty('border', '1px solid rgba(255,255,255,.075)', 'important');
                    el.style.setProperty('border-radius', '14px', 'important');
                    el.style.setProperty('background-color', 'rgba(255,255,255,.022)', 'important');
                    el.style.setProperty('background-image',
                        'linear-gradient(to top, rgba(0,0,0,.30) 0%, rgba(255,255,255,.05) 100%)', 'important');
                    el.style.setProperty('box-shadow',
                        'inset 0 2px 5px rgba(0,0,0,.45), inset 0 -1px 0 rgba(255,255,255,.06)', 'important');
                });
            });

            
            
            
            
            (function buildProfileStats() {
                const host = document.querySelector('#set-content .set-content-left');
                const table = host ? host.querySelector('table.set-table1') : null;
                if (!table || table.dataset.sppStatsDone) return;
                table.dataset.sppStatsDone = '1';
                const items = [];
                Array.prototype.forEach.call(table.querySelectorAll('td'), function (td) {
                    String(td.innerHTML).split(/<br\s*\/?>/i).forEach(function (seg) {
                        const t = seg.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
                        if (!t) return;
                        const m = t.match(/^([^:：]+)[:：]\s*(.*)$/);
                        items.push(m ? { k: m[1].trim(), v: m[2].trim() } : { k: t, v: '' });
                    });
                });
                if (!items.length) return;
                const box = document.createElement('div');
                box.className = 'spp-stats';
                items.forEach(function (it) {
                    const cell = document.createElement('span');
                    cell.className = 'spp-stat' + (/^(SP币|会员头衔)$/.test(it.k) ? ' is-accent' : '');
                    const em = document.createElement('em');   
                    em.textContent = it.k;
                    const b = document.createElement('b');     
                    b.textContent = it.v || '—';
                    cell.appendChild(em);
                    cell.appendChild(b);
                    box.appendChild(cell);
                });
                table.replaceWith(box);
            })();

            
            
            Array.prototype.forEach.call(document.querySelectorAll('#set-menu > li'), function (li) {
                if (li.dataset.sppCurDone) return;
                li.dataset.sppCurDone = '1';
                const a = li.querySelector('a');
                if (!a) return;
                const m = String(a.getAttribute('href') || '').match(/action-([a-z]+)/);
                if (m && SEARCH.indexOf('action-' + m[1]) >= 0) li.classList.add('spp-cur');
            });

            
            
            
            
            (function dropTrailingEmpty() {
                const left = document.querySelector('#set-content .set-content-left');
                if (!left) return;
                const blocks = [...left.children].filter(function (d) { return !d.classList.contains('c'); });
                const last = blocks[blocks.length - 1];
                if (!last || last.dataset.sppEmptyDone) return;
                const txt = (last.textContent || '').replace(/\s+/g, '');
                const hasMedia = !!last.querySelector('img, input, a, select, textarea');
                last.dataset.sppEmptyDone = '1';
                if (!txt && !hasMedia) last.style.setProperty('display', 'none', 'important');
            })();
            
            
            
            
            
            
            const FIELD_SEL = '#set-content input.input, #set-content input[type="text"], #set-content input[type="password"], ' +
                '#set-content input[type="email"], #set-content input[type="number"], #set-content input[type="url"], ' +
                '#set-content input[type="search"], #set-content input[type="tel"], #set-content textarea';
            Array.prototype.forEach.call(document.querySelectorAll(FIELD_SEL), function (el) {
                el.style.setProperty('background-color', 'rgba(9,13,21,.55)', 'important');
                el.style.setProperty('background-image',
                    'linear-gradient(to top, rgba(0,0,0,.30) 0%, rgba(255,255,255,.045) 100%)', 'important');
                el.style.setProperty('border', '1px solid rgba(255,255,255,.10)', 'important');
                el.style.setProperty('color', '#eaf2fb', 'important');
                el.style.setProperty('-webkit-text-fill-color', '#eaf2fb', 'important');
                el.style.setProperty('font-family', 'inherit', 'important');
            });
            
            Array.prototype.forEach.call(document.querySelectorAll('#set-content input[type="file"]'), function (el) {
                el.style.setProperty('background-color', 'rgba(9,13,21,.40)', 'important');
                el.style.setProperty('background-image', 'none', 'important');
                el.style.setProperty('border', '1px dashed rgba(255,255,255,.16)', 'important');
                el.style.setProperty('color', '#9fb0c8', 'important');
                el.style.setProperty('-webkit-text-fill-color', '#9fb0c8', 'important');
                el.style.setProperty('font-family', 'inherit', 'important');
            });
            
            Array.prototype.forEach.call(
                document.querySelectorAll('#set-content input.btn[type="submit"], #set-content input.btn[type="button"], #set-content button.btn'),
                function (el) {
                    el.style.setProperty('background-image', 'none', 'important');
                    el.style.setProperty('background-color', '#188a67', 'important');
                    el.style.setProperty('border', '1px solid rgba(32,201,151,.85)', 'important');
                    el.style.setProperty('color', '#eafff6', 'important');
                    el.style.setProperty('-webkit-text-fill-color', '#eafff6', 'important');
                    el.style.setProperty('font-family', 'inherit', 'important');
                    el.style.setProperty('font-size', '13.5px', 'important');
                }
            );
            Array.prototype.forEach.call(document.querySelectorAll('#set-content input.btn[type="reset"]'), function (el) {
                el.style.setProperty('background-image', 'none', 'important');
                el.style.setProperty('background-color', '#c0392b', 'important');
                el.style.setProperty('border', '1px solid rgba(192,57,43,.9)', 'important');
                el.style.setProperty('color', '#fff', 'important');
                el.style.setProperty('-webkit-text-fill-color', '#fff', 'important');
                el.style.setProperty('font-family', 'inherit', 'important');
            });
        });
    }

    
