    const SPP_STAR_FID = 43;                       
    const SPP_STAR_HEAD = '/* ==================== 2.57.54';
    const SPP_STAR_TAIL = '/* SPP-STAR-END */';
    const SPP_STAR_TAIL_FB = '/* 版头图（站点原图搬进来）*/';
    const SPP_STAR_VER_RE = /\/\* =+ ([0-9]+\.[0-9]+\.[0-9]+)/g;
    const SPP_STAR_VER_OK = { '2.57.54': 1, '2.57.55': 1, '2.57.56': 1 };
    const SPP_SCHEME_STAR = (sppFidNum() === SPP_STAR_FID);

    
    function sppStarLineStart(t, i) {
        const ls = t.lastIndexOf('\n', i - 1);
        return !/\S/.test(t.slice(ls + 1, i));
    }
    
    function sppStarSpanBad(t, a, bStart) {
        if (!sppStarLineStart(t, a)) return '段头不在行首';
        if (!sppStarLineStart(t, bStart)) return '段尾标记不在行首';
        const le = t.indexOf('\n', bStart);
        if (le >= 0 && /\S/.test(t.slice(bStart, le).replace(SPP_STAR_TAIL, '').replace(SPP_STAR_TAIL_FB, ''))) {
            return '段尾标记后面还有别的东西';
        }
        const seg = t.slice(a, bStart);
        let ob = 0;
        let cb = 0;
        for (let i = 0; i < seg.length; i++) {
            const ch = seg.charAt(i);
            if (ch === '{') ob++;
            else if (ch === '}') cb++;
        }
        if (!ob) return '这一段里一条规则也没有';
        if (ob !== cb) return '这一段的 { } 不配平（' + ob + ' / ' + cb + '，说明切在规则中间）';
        SPP_STAR_VER_RE.lastIndex = 0;
        let m;
        let n = 0;
        const seen = {};
        while ((m = SPP_STAR_VER_RE.exec(seg))) {
            n++;
            if (!SPP_STAR_VER_OK[m[1]]) return '这段里混进了别的段头 ' + m[1];
            if (seen[m[1]]) return '段头 ' + m[1] + ' 在这段里出现了两次';
            seen[m[1]] = 1;
        }
        if (!n) return '一段段头也没认出来';
        return '';
    }

    
    
    function sppStarCutCss() {
        const sts = document.querySelectorAll('style');
        let did = false;
        for (let i = 0; i < sts.length; i++) {
            const st = sts[i];
            const t = st.textContent || '';
            if (t.indexOf(SPP_STAR_HEAD) < 0) continue;
            if (st.getAttribute('data-spp-star-cut')) { did = true; continue; }   
            const a = t.indexOf(SPP_STAR_HEAD);
            let bStart = t.indexOf(SPP_STAR_TAIL, a + SPP_STAR_HEAD.length);
            if (bStart < 0) {   
                bStart = t.indexOf(SPP_STAR_TAIL_FB, a + SPP_STAR_HEAD.length);
            }
            if (bStart <= a) {
                console.warn('[SPP] 2.57.56 分派：星舰段的尾标记没找到，这张样式表跳过');
                continue;
            }
            const bad = sppStarSpanBad(t, a, bStart);
            if (bad) {
                console.warn('[SPP] 2.57.56 分派：星舰段不敢剪（' + bad + '），这张样式表跳过');
                continue;
            }
            st.textContent = t.slice(0, a) + t.slice(bStart);
            st.setAttribute('data-spp-star-cut', '1');
            did = true;
        }
        return did;   
    }

    
    
    function sppStarCutWatch() {
        sppStarCutCss();
        onDomReady(function () { sppStarCutCss(); });
        [0, 240, 800, 1600, 2800, 4200].forEach(function (ms) {
            setTimeout(function () { sppStarCutCss(); }, ms);
        });
        try {
            const host = document.head || document.documentElement;
            const mo = new MutationObserver(function (muts) {
                for (let i = 0; i < muts.length; i++) {
                    const ns = muts[i].addedNodes;
                    for (let k = 0; k < ns.length; k++) {
                        const nd = ns[k];
                        if (nd && nd.nodeType === 1 && nd.tagName === 'STYLE') sppStarCutCss();
                    }
                }
            });
            mo.observe(host, { childList: true, subtree: true });
            setTimeout(function () { mo.disconnect(); }, 6000);
        } catch (e) {  }
    }

    
    function sppStarMark() {
        try {
            document.documentElement.setAttribute('data-spp-scheme', SPP_SCHEME_STAR ? 'star' : 'obsidian');
        } catch (e) {  }
    }
    sppStarMark();
    onDomReady(function () { sppStarMark(); });

    if (!SPP_SCHEME_STAR) {
        
        try {
            initSubsStar = function () { return 0; };
            initSubsMeta = function () { return 0; };
            initSubsLayout = function () { return 0; };
        } catch (e) {
            console.warn('[SPP] 2.57.56 分派：星舰三支模块摘除失败', e);
        }
        sppStarCutWatch();
        console.info('[SPP] 2.57.56 样板分派：本页不在星舰名单（fid ' + SPP_STAR_FID +
            '）里 ⇒ 只跑曜石 Bento；星舰那三节 CSS 与三支模块都不生效');
    } else {
        console.info('[SPP] 2.57.56 样板分派：fid ' + SPP_STAR_FID +
            ' ⇒ 典藏星舰（星舰 ＋ 宽奢 ＋ 双行 ＋ 火花条）');
    }

